/* Mini Family Office preparato per Bussola (generato da strumenti/prepara_mfo.py, non modificare a mano) */
const MFO_HTML = "<!DOCTYPE html>\n<html lang=\"it\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<meta name=\"format-detection\" content=\"telephone=no\">\n<title>Mini Family Office — Analisi patrimoniale personale</title>\n<style>\n/* ============================================================\n   MINI FAMILY OFFICE — CSS\n   Design system: variabili, card, wizard, semafori, grafici\n   ============================================================ */\n:root{\n  --bg:#f4f6f9;\n  --card:#ffffff;\n  --ink:#1c2733;\n  --ink-soft:#5a6b7d;\n  --line:#e3e8ef;\n  --brand:#1f4e79;\n  --brand-2:#2e7dba;\n  --accent:#0e8a6d;\n  --ok:#2e9e5b;\n  --ok-bg:#e7f6ec;\n  --warn:#d99a06;\n  --warn-bg:#fdf3d9;\n  --bad:#d64545;\n  --bad-bg:#fdeaea;\n  --radius:14px;\n  --shadow:0 2px 10px rgba(20,40,60,.07);\n  --font:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,\"Helvetica Neue\",Arial,sans-serif;\n}\n*{box-sizing:border-box;margin:0;padding:0}\nhtml{scroll-behavior:smooth}\nbody{font-family:var(--font);background:var(--bg);color:var(--ink);line-height:1.55;font-size:16px}\n.wrap{max-width:960px;margin:0 auto;padding:16px}\nheader.site{background:linear-gradient(135deg,var(--brand) 0%,var(--brand-2) 100%);color:#fff;padding:34px 16px 30px}\nheader.site .wrap{padding:0 16px}\nheader.site h1{font-size:1.6rem;letter-spacing:.2px}\nheader.site p{opacity:.92;margin-top:6px;max-width:640px;font-size:.98rem}\n.badge{display:inline-block;background:rgba(255,255,255,.18);border:1px solid rgba(255,255,255,.4);border-radius:99px;padding:3px 12px;font-size:.78rem;margin-bottom:10px}\n.card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow);padding:22px;margin:16px 0}\n.card h2{font-size:1.18rem;color:var(--brand);margin-bottom:10px}\n.card h3{font-size:1.02rem;margin:14px 0 6px}\n.muted{color:var(--ink-soft);font-size:.92rem}\n.small{font-size:.85rem}\nul.clean{margin:8px 0 8px 20px}\nul.clean li{margin:4px 0}\n/* Bottoni */\n.btn{display:inline-block;border:none;border-radius:10px;padding:12px 22px;font-size:1rem;font-weight:600;cursor:pointer;transition:filter .15s,transform .05s;font-family:inherit}\n.btn:active{transform:translateY(1px)}\n.btn-primary{background:var(--brand);color:#fff}\n.btn-primary:hover{filter:brightness(1.12)}\n.btn-ghost{background:#fff;color:var(--brand);border:1.5px solid var(--brand)}\n.btn-ghost:hover{background:#f0f5fa}\n.btn[disabled]{opacity:.45;cursor:not-allowed}\n.btn-sm{padding:7px 14px;font-size:.85rem;border-radius:8px}\n/* Wizard */\n#progressBarOuter{background:var(--line);border-radius:99px;height:10px;overflow:hidden;margin:10px 0 4px}\n#progressBarInner{background:linear-gradient(90deg,var(--accent),var(--brand-2));height:100%;width:0%;transition:width .3s;border-radius:99px}\n.progress-meta{display:flex;justify-content:space-between;font-size:.82rem;color:var(--ink-soft)}\n.stepchips{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0 2px}\n.stepchip{font-size:.72rem;padding:3px 10px;border-radius:99px;background:#eef2f7;color:var(--ink-soft);border:1px solid var(--line)}\n.stepchip.active{background:var(--brand);color:#fff;border-color:var(--brand)}\n.stepchip.done{background:var(--ok-bg);color:var(--ok);border-color:var(--ok)}\n.q{margin:20px 0;padding:16px;border:1px solid var(--line);border-radius:12px;background:#fbfcfe}\n.q label.qlabel{display:block;font-weight:600;margin-bottom:4px}\n.q .qhelp{font-size:.84rem;color:var(--ink-soft);margin-bottom:10px}\n.q.q-missing{border-color:var(--bad);background:var(--bad-bg)}\n.opts{display:flex;flex-direction:column;gap:8px}\n.opt{display:flex;align-items:center;gap:10px;padding:10px 12px;border:1.5px solid var(--line);border-radius:10px;background:#fff;cursor:pointer;transition:border-color .12s,background .12s;font-size:.95rem}\n.opt:hover{border-color:var(--brand-2)}\n.opt.checked{border-color:var(--brand);background:#eef5fb;font-weight:600}\n.opt input{accent-color:var(--brand);width:18px;height:18px;flex-shrink:0}\nselect.fsel{width:100%;padding:11px 12px;border:1.5px solid var(--line);border-radius:10px;font-size:.95rem;background:#fff;font-family:inherit;color:var(--ink)}\n.precise{margin-top:10px;display:flex;align-items:center;gap:8px;flex-wrap:wrap}\n.precise input{padding:9px 10px;border:1.5px solid var(--line);border-radius:8px;width:160px;font-size:.92rem;font-family:inherit}\n.precise span{font-size:.8rem;color:var(--ink-soft)}\n.wiznav{display:flex;justify-content:space-between;gap:10px;margin-top:20px}\n/* Semafori */\n.light{display:inline-block;width:14px;height:14px;border-radius:50%;flex-shrink:0}\n.light.g{background:var(--ok);box-shadow:0 0 0 4px var(--ok-bg)}\n.light.y{background:var(--warn);box-shadow:0 0 0 4px var(--warn-bg)}\n.light.r{background:var(--bad);box-shadow:0 0 0 4px var(--bad-bg)}\n.lights-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:12px;margin-top:12px}\n.light-card{display:flex;gap:12px;align-items:flex-start;padding:14px;border:1px solid var(--line);border-radius:12px;background:#fff}\n.light-card b{display:block;font-size:.92rem}\n.light-card p{font-size:.82rem;color:var(--ink-soft);margin-top:2px}\n.pill{display:inline-block;border-radius:99px;padding:2px 10px;font-size:.75rem;font-weight:700}\n.pill.g{background:var(--ok-bg);color:var(--ok)}\n.pill.y{background:var(--warn-bg);color:#9a6d00}\n.pill.r{background:var(--bad-bg);color:var(--bad)}\n/* KPI e tabelle */\n.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin:12px 0}\n.kpi{background:#f7f9fc;border:1px solid var(--line);border-radius:12px;padding:12px}\n.kpi .v{font-size:1.15rem;font-weight:700;color:var(--brand)}\n.kpi .l{font-size:.76rem;color:var(--ink-soft);margin-top:2px}\ntable.t{width:100%;border-collapse:collapse;margin:10px 0;font-size:.9rem}\ntable.t th{text-align:left;background:#eef2f7;padding:8px 10px;font-size:.8rem;text-transform:uppercase;letter-spacing:.4px;color:var(--ink-soft)}\ntable.t td{padding:8px 10px;border-bottom:1px solid var(--line)}\ntable.t tr:last-child td{border-bottom:none}\ntable.t td.num{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}\n.trow-tot td{font-weight:700;background:#f7f9fc}\n/* Simulatore */\n.sim-controls{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin:14px 0}\n.sim-ctl{background:#f7f9fc;border:1px solid var(--line);border-radius:12px;padding:14px}\n.sim-ctl label{font-size:.85rem;font-weight:600;display:flex;justify-content:space-between;margin-bottom:8px}\n.sim-ctl label output{color:var(--brand);font-weight:700}\ninput[type=range]{width:100%;accent-color:var(--brand);height:26px}\n.sim-note{font-size:.8rem;color:var(--ink-soft);margin-top:4px}\n/* Allocazioni */\n.alloc-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px;margin-top:12px}\n.alloc-card{border:1.5px solid var(--line);border-radius:12px;padding:16px;background:#fff}\n.alloc-card.suggested{border-color:var(--accent);box-shadow:0 0 0 3px rgba(14,138,109,.12)}\n.alloc-card h4{font-size:.98rem;margin-bottom:2px}\n.alloc-card .tag{font-size:.72rem;color:var(--accent);font-weight:700;text-transform:uppercase;letter-spacing:.5px}\n.alloc-row{display:flex;justify-content:space-between;font-size:.85rem;padding:5px 0;border-bottom:1px dashed var(--line)}\n.alloc-row:last-child{border-bottom:none}\n.alloc-row b{font-variant-numeric:tabular-nums}\n/* Report semplice */\n.simple-block{border-left:4px solid var(--brand-2);background:#f7fafd;border-radius:0 10px 10px 0;padding:12px 16px;margin:10px 0}\n.simple-block h4{font-size:.95rem;margin-bottom:4px;color:var(--brand)}\n.simple-block p, .simple-block li{font-size:.92rem}\n/* Tips */\n.tip{border:1px solid var(--line);border-radius:12px;padding:14px;margin:10px 0;background:#fff}\n.tip b{font-size:.92rem}\n.tip p{font-size:.87rem;margin-top:3px}\n.tip .src{font-size:.76rem;color:var(--ink-soft);font-style:italic;margin-top:5px}\n/* Riepilogo */\n.rec-row{display:flex;justify-content:space-between;gap:12px;padding:8px 0;border-bottom:1px solid var(--line);font-size:.9rem}\n.rec-row:last-child{border-bottom:none}\n.rec-row .rl{color:var(--ink-soft)}\n.rec-row .rv{font-weight:600;text-align:right}\n.rec-row a{color:var(--brand-2);font-size:.78rem;margin-left:8px;cursor:pointer;text-decoration:underline}\n/* Grafici */\n.chart-box{margin:14px 0;overflow-x:auto}\n.chart-box svg{max-width:100%;height:auto;display:block;margin:0 auto}\n.chart-title{font-size:.88rem;font-weight:700;color:var(--ink-soft);margin:14px 0 4px;text-transform:uppercase;letter-spacing:.4px}\n.legend{display:flex;flex-wrap:wrap;gap:12px;font-size:.8rem;color:var(--ink-soft);margin-top:6px;justify-content:center}\n.legend i{display:inline-block;width:11px;height:11px;border-radius:3px;margin-right:5px;vertical-align:-1px}\n/* Alert */\n.alert{border-radius:10px;padding:12px 14px;margin:10px 0;font-size:.9rem;display:flex;gap:10px;align-items:flex-start}\n.alert.warn{background:var(--warn-bg);border:1px solid #ecd08e;color:#7a5800}\n.alert.bad{background:var(--bad-bg);border:1px solid #efb6b6;color:#8f2626}\n.alert.ok{background:var(--ok-bg);border:1px solid #a9dcbd;color:#1d6b3d}\n.alert.info{background:#e8f1fa;border:1px solid #bcd6ec;color:#274e6e}\n/* Nav risultati */\n.resnav{position:sticky;top:0;z-index:20;background:rgba(244,246,249,.95);backdrop-filter:blur(4px);padding:8px 0;display:flex;gap:6px;flex-wrap:wrap;border-bottom:1px solid var(--line)}\n.resnav a{font-size:.78rem;padding:6px 12px;border-radius:99px;background:#fff;border:1px solid var(--line);color:var(--ink-soft);text-decoration:none;font-weight:600}\n.resnav a:hover{border-color:var(--brand);color:var(--brand)}\nfooter.site{padding:26px 16px 40px;color:var(--ink-soft);font-size:.8rem;text-align:center}\n/* ============ Gamification (facoltativa) ============ */\n.game-box{display:flex;gap:12px;align-items:flex-start;background:#f2f7f4;border:1.5px dashed var(--accent);border-radius:12px;padding:14px;margin-top:16px}\n.game-box p{font-size:.88rem}\n.gswitch{position:relative;display:inline-block;width:46px;height:26px;flex-shrink:0}\n.gswitch input{opacity:0;width:0;height:0}\n.gslider{position:absolute;cursor:pointer;inset:0;background:#c4ccd6;border-radius:99px;transition:.2s}\n.gslider:before{content:\"\";position:absolute;height:20px;width:20px;left:3px;bottom:3px;background:#fff;border-radius:50%;transition:.2s}\n.gswitch input:checked + .gslider{background:var(--accent)}\n.gswitch input:checked + .gslider:before{transform:translateX(20px)}\n#xpWrap{margin:10px 0 2px}\n#xpBarOuter{background:var(--line);border-radius:99px;height:8px;overflow:hidden}\n#xpBar{background:linear-gradient(90deg,#e6a817,#0e8a6d);height:100%;width:0%;transition:width .4s;border-radius:99px}\n.xp-label{display:flex;justify-content:space-between;font-size:.76rem;color:var(--ink-soft);margin-top:3px}\n.xp-label b{color:var(--accent)}\n.badge-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px;margin-top:12px}\n.badge-card{border:1.5px solid var(--accent);border-radius:12px;padding:14px;background:#f4faf7;text-align:center}\n.badge-card .bic{font-size:1.9rem}\n.badge-card b{display:block;font-size:.9rem;margin:4px 0 2px}\n.badge-card p{font-size:.76rem;color:var(--ink-soft)}\n.badge-card.locked{border-color:var(--line);background:#f7f8fa;filter:grayscale(1);opacity:.65}\n.badge-card.locked .bic{opacity:.5}\n.mission{display:flex;gap:12px;align-items:flex-start;border:1px solid var(--line);border-left:4px solid var(--warn);border-radius:10px;padding:12px 14px;margin:10px 0;background:#fff}\n.mission .mic{font-size:1.4rem}\n.mission b{font-size:.92rem}\n.mission p{font-size:.84rem;color:var(--ink-soft);margin-top:2px}\n.mission .mpts{margin-left:auto;flex-shrink:0;background:var(--warn-bg);color:#9a6d00;border-radius:99px;padding:3px 10px;font-size:.75rem;font-weight:700;white-space:nowrap}\n.toast-wrap{position:fixed;bottom:18px;left:50%;transform:translateX(-50%);z-index:99;display:flex;flex-direction:column;gap:8px;align-items:center;pointer-events:none}\n.toast{background:var(--ink);color:#fff;padding:9px 18px;border-radius:99px;font-size:.85rem;box-shadow:0 4px 14px rgba(0,0,0,.25);animation:toastIn .25s ease-out, toastOut .4s ease-in 2.4s forwards}\n@keyframes toastIn{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}\n@keyframes toastOut{to{opacity:0;transform:translateY(10px)}}\n.confetti{position:fixed;top:-14px;width:9px;height:14px;z-index:98;pointer-events:none;border-radius:2px;animation:confFall linear forwards}\n@keyframes confFall{to{transform:translateY(105vh) rotate(720deg)}}\n@media print{.toast-wrap,.confetti{display:none!important}}\n@media (max-width:640px){\n  body{font-size:15px}\n  .card{padding:16px}\n  header.site h1{font-size:1.3rem}\n  .wiznav{flex-direction:column-reverse}\n  .wiznav .btn{width:100%}\n}\n@media print{\n  header.site,.resnav,.wiznav,.btn,#simControls{display:none!important}\n  body{background:#fff}\n  .card{box-shadow:none;border-color:#ccc;break-inside:avoid}\n}\n\n/* ---- adattamento Bussola: stessa grafica dell'app (colori, carattere, misure) ---- */\n:root{ --brand:#294d95; --brand-2:#23507d; --accent:#1f7a4d; --ok:#1f7a4d; --ok-bg:#e5f3ec; --warn:#9a5b00; --warn-bg:#fdf1dc;\n  --bad:#a3272b; --bad-bg:#fbe6e6; --bg:#f4f7fa; --card:#fff; --line:#d9e2ef; --ink:#282828; --ink-soft:#5b6573;\n  --radius:14px; --shadow:none;\n  --font:\"Poppins\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,\"Helvetica Neue\",Arial,sans-serif; }\nhtml{font-size:17px} body{font-size:1rem;line-height:1.45;background:var(--bg)}\nheader.site{display:none}\n.wrap{max-width:none;padding:0 0 8px}\n.card{border:1px solid var(--line);border-radius:14px;box-shadow:none;padding:18px 16px;margin:0 0 12px}\n.card h2{font-size:1.3rem;font-weight:700;color:var(--ink);margin-bottom:8px}\n.card h3{font-size:1.05rem;color:var(--ink)}\n.muted{font-size:.9rem}\n.btn{min-height:52px;border-radius:12px;padding:0 20px;font-size:1rem;font-weight:600;display:inline-flex;align-items:center;justify-content:center;gap:8px}\n.btn-primary{background:var(--brand)} .btn-primary:hover{filter:none;background:var(--brand-2)}\n.btn-ghost{border:1px solid var(--line);color:var(--ink);background:#fff}\n.btn-sm{min-height:40px;padding:0 12px;font-size:.85rem}\n.wiznav{margin-top:16px} .wiznav .btn{flex:1}\n#progressBarOuter{height:6px;background:var(--line)} #progressBarInner{background:var(--accent)}\n.progress-meta{font-size:.85rem}\n.stepchips{gap:6px} .stepchip{font-size:.8rem;padding:5px 12px;background:#fff}\n.stepchip.active{background:var(--brand)} .stepchip.done{background:var(--ok-bg)}\n.q{margin:0 0 12px;padding:14px;border:1px solid var(--line);border-radius:14px;background:#fff}\n.q label.qlabel{font-size:1rem;font-weight:600;margin-bottom:8px}\n.q .qhelp{font-size:.85rem}\n.opts{gap:8px}\n.opt{min-height:48px;padding:10px 14px;border:1px solid var(--line);border-radius:10px;background:#fbfcfd;font-size:.95rem;font-weight:500}\n.opt:hover{border-color:var(--brand)}\n.opt.checked{background:var(--brand);border-color:var(--brand);color:#fff;font-weight:600}\n.opt.checked input{accent-color:#fff}\nselect.fsel,.precise input{min-height:50px;border:1px solid var(--line);border-radius:10px;font-size:1rem;background:#fbfcfd}\n.precise input{width:200px}\n.kpi{background:#fff;border-radius:14px} .kpi .v{font-size:1.25rem}\n.light-card,.alloc-card,.tip,.badge-card,.mission{border-radius:14px}\n.alert{border-radius:10px}\n.resnav{background:rgba(244,247,250,.97)}\n.resnav a{font-size:.85rem;padding:8px 14px}\n#xpBar{background:var(--accent)}\nfooter.site{display:none}\n@media (min-width:900px){ html{font-size:16px} .card{padding:22px 24px} .opts{display:grid;grid-template-columns:1fr 1fr} }\n</style>\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;600;700&display=swap\" rel=\"stylesheet\">\n</head>\n<body>\n\n<header class=\"site\">\n  <div class=\"wrap\">\n    <span class=\"badge\">Strumento educativo · v1.0 · Lloyd Varesino</span>\n    <h1>🏛️ Mini Family Office personale</h1>\n    <p>Una prima analisi guidata di patrimonio, cash flow, rischio, debiti e protezioni — con report semplificato e avanzato. Non è consulenza finanziaria: è un punto di partenza per capire dove sei.</p>\n  </div>\n</header>\n\n<div class=\"wrap\">\n\n  <\!-- ============ 1. INTRODUZIONE E DISCLAIMER ============ -->\n  <section id=\"intro\" class=\"card\">\n    <\!-- Avviso mostrato solo se il JavaScript risulta bloccato (es. anteprima Quick Look su iPhone) -->\n    <div id=\"jsWarn\" class=\"alert bad\">⚠️ <div><b>JavaScript non attivo: l'app non può funzionare in questa modalità.</b><br>\n    Su iPhone/iPad l'anteprima dell'app File blocca il codice. Soluzioni: apri il file con un'app gratuita come <b>Documents (Readdle)</b>, oppure pubblica la pagina online (es. Netlify Drop, GitHub Pages) e aprila in <b>Safari</b>. Su computer basta il doppio clic.</div></div>\n    <h2>Come funziona</h2>\n    <p>Si parte da una <b>pagina di orientamento</b> (età, orizzonte, obiettivo, coppia, livello di approfondimento) che dimensiona il resto del questionario su tre percorsi: <b>Light</b> (~15 domande, analisi più imprecisa), <b>Standard</b> (~25–30) o <b>Approfondito</b> (fino a ~38, <b>consigliato</b>: include fiscalità, fase di utilizzo del capitale e analisi di coppia più ricca). Al termine otterrai:</p>\n    <ul class=\"clean\">\n      <li>una <b>fotografia del tuo patrimonio</b> e del tuo equilibrio finanziario;</li>\n      <li>una <b>valutazione a semaforo</b> delle aree chiave (liquidità, debiti, protezioni, rischio…);</li>\n      <li>un <b>report semplificato</b> in linguaggio chiaro e un <b>report avanzato</b> con tabelle, indicatori e grafici;</li>\n      <li>un <b>simulatore prudente</b> per esplorare l'effetto di risparmio, orizzonte e allocazione;</li>\n      <li><b>3 proposte di allocazione indicative</b> coerenti con il tuo profilo;</li>\n      <li>principi guida ispirati alla letteratura finanziaria.</li>\n    </ul>\n    <h3>⚠️ Disclaimer</h3>\n    <p class=\"muted\">Questo strumento è <b>educativo e orientativo</b>. Non costituisce consulenza finanziaria, assicurativa, fiscale o legale personalizzata. Le simulazioni si basano su ipotesi semplificate e rendimenti attesi prudenti: <b>non sono previsioni né garanzia di risultati futuri</b>. Per qualsiasi decisione reale confrontati con consulenti abilitati (consulente finanziario, intermediario assicurativo, commercialista, avvocato).</p>\n    <h3>🔒 Privacy</h3>\n    <p class=\"muted\">Tutti i calcoli avvengono <b>localmente nel tuo browser</b>. I calcoli avvengono sul dispositivo. Le risposte arrivano all'agenzia solo alla fine, se il cliente chiede di essere ricontattato. La pagina funziona anche offline.</p>\n    <div class=\"game-box\">\n      <label class=\"gswitch\"><input type=\"checkbox\" id=\"gameToggle\" checked><span class=\"gslider\"></span></label>\n      <p><b>🎮 Modalità gioco (facoltativa)</b><br>Guadagna punti rispondendo, sblocca trofei legati alla tua reale salute finanziaria e ricevi missioni concrete su cui lavorare. È solo un modo più coinvolgente di fare la stessa identica analisi: puoi disattivarla quando vuoi e i risultati non cambiano.</p>\n    </div>\n    <div style=\"margin-top:18px\">\n      <button class=\"btn btn-primary\" data-action=\"start\">Inizia l'analisi →</button>\n    </div>\n  </section>\n\n  <\!-- ============ 2. QUESTIONARIO (wizard) ============ -->\n  <section id=\"wizard\" class=\"card\" hidden>\n    <div class=\"progress-meta\"><span id=\"stepTitle\"></span><span id=\"qCounter\"></span></div>\n    <div id=\"progressBarOuter\"><div id=\"progressBarInner\"></div></div>\n    <div id=\"xpWrap\" hidden>\n      <div id=\"xpBarOuter\"><div id=\"xpBar\"></div></div>\n      <div class=\"xp-label\"><b id=\"xpLevel\"></b><span id=\"xpPts\"></span></div>\n    </div>\n    <div class=\"stepchips\" id=\"stepChips\"></div>\n    <div id=\"stepBody\"></div>\n    <div class=\"wiznav\">\n      <button class=\"btn btn-ghost\" id=\"btnPrev\" data-action=\"prev\">← Indietro</button>\n      <button class=\"btn btn-primary\" id=\"btnNext\" data-action=\"next\">Avanti →</button>\n    </div>\n  </section>\n\n  <\!-- ============ 3–11. RISULTATI ============ -->\n  <section id=\"results\" hidden>\n    <nav class=\"resnav\">\n      <a href=\"#secLights\">Semafori</a>\n      <a href=\"#secBadges\">Trofei</a>\n      <a href=\"#secMissions\">Missioni</a>\n      <a href=\"#secSimple\">Report semplice</a>\n      <a href=\"#secSim\">Simulatore</a>\n      <a href=\"#secAlloc\">Allocazioni</a>\n      <a href=\"#secAdv\">Report avanzato</a>\n      <a href=\"#secTips\">Principi guida</a>\n      <a href=\"#secLimits\">Limiti</a>\n    </nav>\n    <div id=\"resultsBody\"></div>\n    <div class=\"card\" style=\"text-align:center\">\n      <button class=\"btn btn-ghost\" data-action=\"print\">🖨️ Stampa / salva PDF</button>\n      <button class=\"btn btn-ghost\" id=\"btnRestart\" data-action=\"restart\">↺ Ricomincia</button>\n    </div>\n  </section>\n\n</div>\n\n<footer class=\"site\">\n  Mini Family Office · strumento educativo · i dati restano sul dispositivo fino all'invio all'agenzia · non è consulenza personalizzata.\n</footer>\n\n<script>\n\"use strict\";\n/* ============================================================\n   CONFIGURAZIONE QUESTIONARIO\n   30 domande in 8 step + riepilogo + risultati.\n   Ogni opzione ha \"mid\" = valore centrale usato nei calcoli.\n   ============================================================ */\n\n// FLUSSO ADATTIVO SU 4 PAGINE + riepilogo + risultati.\n// La PRIMA PAGINA contiene solo le domande di indirizzamento (età, orizzonte,\n// obiettivo, inclusione del partner, livello di approfondimento) che decidono\n// quali domande verranno poste nelle pagine successive:\n//   - Light:        ~15 domande (analisi più imprecisa, basata su stime)\n//   - Standard:     ~25–30 domande\n//   - Approfondito: fino a ~38 domande (CONSIGLIATO: fotografia più accurata)\nconst STEPS = [\n  {id:'p0', title:'1 · Per iniziare', sections:['iniziali']},\n  {id:'p1', title:'2 · Persona, famiglia e reddito', sections:['personali','famiglia','reddito']},\n  {id:'p2', title:'3 · Patrimonio, impegni e obiettivi', sections:['patrimonio','debiti','obiettivi','decumulo']},\n  {id:'p3', title:'4 · Rischio e protezioni', sections:['rischio','assicurazioni']},\n  {id:'riepilogo', title:'5 · Riepilogo', sections:[]},\n  {id:'risultati', title:'6 · Risultati', sections:[]}\n];\nconst SECTION_TITLES = {\n  iniziali:'🚀 Per iniziare', personali:'👤 Dati personali', famiglia:'👨‍👩‍👧 Famiglia e coppia', reddito:'💶 Reddito e spese',\n  patrimonio:'🏦 Patrimonio', debiti:'📉 Impegni finanziari', obiettivi:'🎯 Obiettivi',\n  decumulo:'🌅 Fase di utilizzo del capitale', rischio:'⚖️ Rischio e investimenti', assicurazioni:'🛡️ Coperture assicurative'\n};\n\n// --- Livello di approfondimento (1=Light, 2=Standard, 3=Approfondito) ---\n// Finché l'utente non sceglie, si assume il percorso consigliato (Approfondito).\nfunction tier(){\n  if (A.approfondimento === 'light') return 1;\n  if (A.approfondimento === 'standard') return 2;\n  return 3;\n}\nfunction tierName(){ return ['', 'Light', 'Standard', 'Approfondito'][tier()]; }\nfunction T2(){ return tier() >= 2; }\nfunction T3(){ return tier() >= 3; }\nfunction deepMode(){ return tier() >= 2; } // dati di dettaglio disponibili (Standard/Approfondito)\nfunction isFI(){ return A.obiettivo === 'rendita' || A.obiettivo === 'pensione'; }\nfunction hasPartner(){ return A.includiPartner === 'si' || A.includiPartner === 'solo_io'; }\nfunction coupleMode(){ return A.includiPartner === 'si'; }\n\nconst QUESTIONS = [\n// ---------- SEZIONE INIZIALE: guida l'intero percorso ----------\n{id:'eta', step:'iniziali', type:'radio', label:'Qual è la tua età?', options:[\n  {v:'u30', l:'Meno di 30 anni', mid:27},{v:'30_39', l:'30–39 anni', mid:35},\n  {v:'40_49', l:'40–49 anni', mid:45},{v:'50_59', l:'50–59 anni', mid:55},\n  {v:'60_69', l:'60–69 anni', mid:65},{v:'70p', l:'70 anni o più', mid:75}]},\n{id:'orizzonte', step:'iniziali', type:'radio', label:'Su quale orizzonte temporale vuoi pianificare?',\n help:'Quanto tempo hai davanti prima di usare la maggior parte del capitale che accumuli.', options:[\n  {v:'breve', l:'Meno di 5 anni', mid:4},{v:'medio', l:'5–10 anni', mid:7},\n  {v:'lungo', l:'10–20 anni', mid:15},{v:'moltolungo', l:'Oltre 20 anni', mid:25}]},\n{id:'obiettivo', step:'iniziali', type:'select', label:'Qual è il tuo obiettivo finanziario principale?', options:[\n  {v:'emergenza', l:'Costruire un fondo di emergenza'},\n  {v:'casa', l:'Acquistare o cambiare casa'},\n  {v:'figli', l:'Educazione / futuro dei figli'},\n  {v:'pensione', l:'Integrazione pensionistica'},\n  {v:'crescita', l:'Far crescere il patrimonio'},\n  {v:'rendita', l:'Rendita / indipendenza finanziaria'},\n  {v:'protezione', l:'Proteggere la famiglia'}]},\n{id:'includiPartner', step:'iniziali', type:'radio', label:'Vuoi includere il tuo coniuge/partner nell’analisi?',\n help:'Includendo il partner valuteremo anche quanto reddito porta ciascuno di voi e gli eventuali rischi per il patrimonio familiare legati alla sua attività professionale.', options:[\n  {v:'si', l:'Sì: analisi di coppia (consigliato se convivete)'},\n  {v:'solo_io', l:'Ho un partner, ma analizzate solo me'},\n  {v:'no_partner', l:'Non ho un coniuge/partner'}]},\n{id:'approfondimento', step:'iniziali', type:'radio', label:'Quanto vuoi approfondire l’analisi?',\n help:'Consigliamo il percorso Approfondito: più domande ma fotografia molto più accurata. ⚠️ Attenzione: con il percorso Light l’analisi sarà più imprecisa, perché molti dati verranno stimati con ipotesi standard.', options:[\n  {v:'approfondito', l:'Approfondito: analisi dettagliata, fino a ~38 domande (consigliato)'},\n  {v:'standard', l:'Standard: buon equilibrio tra dettaglio e velocità (~25–30 domande)'},\n  {v:'light', l:'Light: solo l’essenziale, ~15 domande (analisi più imprecisa)'}]},\n\n// ---------- SEZIONE: DATI PERSONALI ----------\n{id:'residenza', step:'personali', type:'select', label:'Dove vivi?', visibleIf: T3, options:[\n  {v:'nord', l:'Nord Italia'},{v:'centro', l:'Centro Italia'},\n  {v:'sud', l:'Sud Italia e Isole'},{v:'estero', l:'Estero'}]},\n\n// ---------- SEZIONE: FAMIGLIA E COPPIA ----------\n{id:'dipendenti', step:'famiglia', type:'radio', label:'Quante persone dipendono economicamente da te (figli o altri)?', options:[\n  {v:'0', l:'Nessuna', mid:0},{v:'1', l:'1 persona', mid:1},\n  {v:'2', l:'2 persone', mid:2},{v:'3p', l:'3 o più persone', mid:3}]},\n{id:'quotaReddito', step:'famiglia', type:'radio', label:'Come si divide il reddito familiare tra te e il tuo partner?',\n visibleIf: coupleMode, options:[\n  {v:'solo_io', l:'Praticamente solo io', share:1.0},\n  {v:'prev_io', l:'Prevalentemente io (circa 70/30)', share:0.7},\n  {v:'meta', l:'Circa metà ciascuno', share:0.5},\n  {v:'prev_partner', l:'Prevalentemente il partner (circa 30/70)', share:0.3},\n  {v:'solo_partner', l:'Praticamente solo il partner', share:0.0}]},\n{id:'responsabilita', step:'famiglia', type:'multi', label:'Ricopri ruoli con responsabilità patrimoniali personali particolari?',\n visibleIf: function(){ return T2() || coupleMode(); },\n help:'Alcuni ruoli espongono il patrimonio personale a rischi specifici. Seleziona tutto ciò che ti riguarda.', options:[\n  {v:'albo', l:'Professionista iscritto ad albo (medico, avvocato, ingegnere…)'},\n  {v:'amministratore', l:'Amministratore di società'},\n  {v:'sindaco', l:'Sindaco o revisore di società'},\n  {v:'snc', l:'Socio di SNC'},\n  {v:'sas', l:'Socio accomandatario di SAS'},\n  {v:'altro', l:'Altro ruolo con responsabilità personale'},\n  {v:'nessuna', l:'Nessuno di questi', exclusive:true}]},\n{id:'responsabilitaPartner', step:'famiglia', type:'multi', label:'Il tuo partner ricopre ruoli con responsabilità patrimoniali particolari?',\n visibleIf: coupleMode,\n help:'L’attività professionale del partner può esporre il patrimonio familiare, soprattutto in regime di comunione dei beni.', options:[\n  {v:'albo', l:'Professionista iscritto ad albo'},\n  {v:'amministratore', l:'Amministratore di società'},\n  {v:'sindaco', l:'Sindaco o revisore di società'},\n  {v:'snc', l:'Socio di SNC'},\n  {v:'sas', l:'Socio accomandatario di SAS'},\n  {v:'altro', l:'Altro ruolo con responsabilità personale'},\n  {v:'nessuna', l:'Nessuno di questi', exclusive:true}]},\n\n// ---------- SEZIONE: REDDITO E SPESE ----------\n{id:'fonteReddito', step:'reddito', type:'select', label:'Qual è la fonte principale del reddito familiare?', visibleIf: T2, options:[\n  {v:'dip_ind', l:'Lavoro dipendente a tempo indeterminato'},\n  {v:'dip_det', l:'Lavoro dipendente a termine'},\n  {v:'autonomo', l:'Lavoro autonomo / libera professione'},\n  {v:'impresa', l:'Impresa propria'},\n  {v:'pensione', l:'Pensione'},\n  {v:'rendite', l:'Rendite (affitti, capitali)'},\n  {v:'misto', l:'Misto / altro'}]},\n{id:'stabilita', step:'reddito', type:'radio', label:'Quanto è stabile il tuo reddito?', visibleIf: T2, options:[\n  {v:'molto', l:'Molto stabile e prevedibile'},{v:'abbastanza', l:'Abbastanza stabile'},\n  {v:'variabile', l:'Variabile di anno in anno'},{v:'molto_var', l:'Molto variabile o incerto'}]},\n{id:'reddito', step:'reddito', type:'radio', label:'Reddito annuo netto complessivo del nucleo familiare', precise:true, unit:'€/anno', options:[\n  {v:'r1', l:'Meno di 15.000 €', mid:12000},{v:'r2', l:'15.000–25.000 €', mid:20000},\n  {v:'r3', l:'25.000–40.000 €', mid:32000},{v:'r4', l:'40.000–60.000 €', mid:50000},\n  {v:'r5', l:'60.000–100.000 €', mid:80000},{v:'r6', l:'Oltre 100.000 €', mid:130000}]},\n{id:'spesaMensile', step:'reddito', type:'radio', label:'Spesa mensile media della famiglia (tutto incluso, comprese le rate)', precise:true, unit:'€/mese', options:[\n  {v:'s1', l:'Meno di 1.000 €', mid:800},{v:'s2', l:'1.000–1.500 €', mid:1250},\n  {v:'s3', l:'1.500–2.500 €', mid:2000},{v:'s4', l:'2.500–4.000 €', mid:3200},\n  {v:'s5', l:'Oltre 4.000 €', mid:5000}]},\n{id:'risparmioMensile', step:'reddito', type:'radio', label:'Quanto riesci a risparmiare in media ogni mese?', precise:true, unit:'€/mese', options:[\n  {v:'0', l:'Nulla o quasi', mid:0},{v:'a', l:'Meno di 100 €', mid:50},\n  {v:'b', l:'100–250 €', mid:175},{v:'c', l:'250–500 €', mid:375},\n  {v:'d', l:'500–1.000 €', mid:750},{v:'e', l:'Oltre 1.000 €', mid:1500}]},\n{id:'fondoEmergenza', step:'reddito', type:'radio', label:'Hai un fondo di emergenza dedicato?', visibleIf: T2,\n help:'Denaro accantonato e subito disponibile per imprevisti, separato dagli investimenti.', options:[\n  {v:'no', l:'No, non ho riserve dedicate'},\n  {v:'liquidita', l:'Uso la liquidità generica sul conto'},\n  {v:'lt3', l:'Sì, copre meno di 3 mesi di spese'},\n  {v:'m3_6', l:'Sì, copre 3–6 mesi di spese'},\n  {v:'gt6', l:'Sì, copre oltre 6 mesi di spese'}]},\n\n// ---------- STEP 4: PATRIMONIO ----------\n{id:'liquidita', step:'patrimonio', type:'radio', label:'Liquidità totale (conti correnti, depositi)', precise:true, unit:'€', options:[\n  {v:'l1', l:'Meno di 5.000 €', mid:2500},{v:'l2', l:'5.000–15.000 €', mid:10000},\n  {v:'l3', l:'15.000–30.000 €', mid:22000},{v:'l4', l:'30.000–60.000 €', mid:45000},\n  {v:'l5', l:'60.000–100.000 €', mid:80000},{v:'l6', l:'Oltre 100.000 €', mid:150000}]},\n{id:'investimenti', step:'patrimonio', type:'radio', label:'Investimenti finanziari (fondi, ETF, azioni, obbligazioni, polizze di investimento)', precise:true, unit:'€', options:[\n  {v:'0', l:'Nessuno', mid:0},{v:'i1', l:'Meno di 10.000 €', mid:5000},\n  {v:'i2', l:'10.000–25.000 €', mid:17500},{v:'i3', l:'25.000–50.000 €', mid:37500},\n  {v:'i4', l:'50.000–100.000 €', mid:75000},{v:'i5', l:'100.000–250.000 €', mid:175000},\n  {v:'i6', l:'Oltre 250.000 €', mid:400000}]},\n{id:'tipoStrumenti', step:'patrimonio', type:'select', label:'Dove sono investiti oggi prevalentemente i tuoi capitali?',\n visibleIf: function(){ return T3() && A.investimenti !== undefined && A.investimenti !== '0'; },\n help:'Serve anche per stimare la fiscalità: i titoli di Stato sono tassati al 12,5%, gli altri strumenti al 26%.', options:[\n  {v:'deposito', l:'Conti deposito / liquidità remunerata'},\n  {v:'titoli_stato', l:'Titoli di Stato / obbligazioni governative'},\n  {v:'fondi', l:'Fondi comuni / ETF diversificati'},\n  {v:'azioni', l:'Azioni singole'},\n  {v:'misto', l:'Un mix di più strumenti'}]},\n{id:'immobili', step:'patrimonio', type:'radio', label:'Valore stimato degli immobili di proprietà (inclusa prima casa)', precise:true, unit:'€', visibleIf: T2, options:[\n  {v:'0', l:'Nessun immobile', mid:0},{v:'m1', l:'Meno di 100.000 €', mid:75000},\n  {v:'m2', l:'100.000–250.000 €', mid:175000},{v:'m3', l:'250.000–500.000 €', mid:350000},\n  {v:'m4', l:'Oltre 500.000 €', mid:700000}]},\n{id:'previdenza', step:'patrimonio', type:'radio', label:'Previdenza integrativa (fondo pensione, PIP)', visibleIf: T2, options:[\n  {v:'0', l:'Non ne ho', mid:0},{v:'p1', l:'Sì, meno di 10.000 € accumulati', mid:5000},\n  {v:'p2', l:'Sì, 10.000–50.000 €', mid:25000},{v:'p3', l:'Sì, oltre 50.000 €', mid:80000}]},\n{id:'contribuzionePrevidenza', step:'patrimonio', type:'radio', label:'Quanto versi oggi alla previdenza integrativa?', visibleIf: T3,\n help:'I versamenti sono deducibili fino a circa 5.164 € l’anno: un vantaggio fiscale immediato.', options:[\n  {v:'0', l:'Nulla', mid:0},{v:'v1', l:'Meno di 100 €/mese', mid:50},\n  {v:'v2', l:'100–300 €/mese', mid:200},{v:'v3', l:'Oltre 300 €/mese', mid:400}]},\n{id:'altriAsset', step:'patrimonio', type:'radio', label:'Altri asset rilevanti (quote societarie, oro, arte, cripto…)', visibleIf: T3, options:[\n  {v:'0', l:'Nessuno', mid:0},{v:'a1', l:'Meno di 25.000 €', mid:12500},\n  {v:'a2', l:'25.000–100.000 €', mid:60000},{v:'a3', l:'Oltre 100.000 €', mid:150000}]},\n\n// ---------- SEZIONE: IMPEGNI FINANZIARI ----------\n// Domanda \"porta\": se l'utente seleziona \"Nessuno\", le altre 4 domande\n// vengono compilate automaticamente come \"nessun impegno\" e nascoste.\n{id:'tipiDebiti', step:'debiti', type:'multi', label:'Quali impegni finanziari hai attualmente?',\n help:'Se non ne hai, seleziona \"Nessuno\": le altre domande su questo tema verranno saltate automaticamente.', options:[\n  {v:'mutuo', l:'Mutuo'},\n  {v:'prestiti', l:'Prestiti personali'},{v:'auto', l:'Finanziamento auto'},\n  {v:'leasing', l:'Leasing'},{v:'revolving', l:'Carte revolving'},\n  {v:'altri', l:'Altri debiti'},{v:'nessuno', l:'Nessuno', exclusive:true}]},\n{id:'mutuo', step:'debiti', type:'radio', label:'Debito residuo del mutuo', precise:true, unit:'€',\n visibleIf: function(){ return T2() && (A.tipiDebiti || []).includes('mutuo'); }, options:[\n  {v:'0', l:'Nessun mutuo', mid:0},{v:'d1', l:'Meno di 50.000 €', mid:30000},\n  {v:'d2', l:'50.000–100.000 €', mid:75000},{v:'d3', l:'100.000–200.000 €', mid:150000},\n  {v:'d4', l:'Oltre 200.000 €', mid:250000}]},\n{id:'altriDebitiTot', step:'debiti', type:'radio', label:'Totale residuo degli altri debiti (esclusi mutui)', precise:true, unit:'€',\n visibleIf: function(){ return T2() && (A.tipiDebiti || []).some(function(v){ return ['prestiti','auto','leasing','revolving','altri'].includes(v); }); }, options:[\n  {v:'0', l:'Nessuno', mid:0},{v:'e1', l:'Meno di 10.000 €', mid:5000},\n  {v:'e2', l:'10.000–30.000 €', mid:20000},{v:'e3', l:'Oltre 30.000 €', mid:45000}]},\n{id:'rataMensile', step:'debiti', type:'radio', label:'Rata mensile totale di tutti gli impegni (mutuo + prestiti + leasing…)', precise:true, unit:'€/mese',\n visibleIf: function(){ const td = A.tipiDebiti || []; return td.length > 0 && !td.includes('nessuno'); }, options:[\n  {v:'0', l:'Nessuna rata', mid:0},{v:'t1', l:'Meno di 300 €', mid:200},\n  {v:'t2', l:'300–600 €', mid:450},{v:'t3', l:'600–1.000 €', mid:800},\n  {v:'t4', l:'Oltre 1.000 €', mid:1300}]},\n{id:'durataImpegni', step:'debiti', type:'radio', label:'Durata residua dell’impegno più lungo',\n visibleIf: function(){ const td = A.tipiDebiti || []; return T2() && td.length > 0 && !td.includes('nessuno'); }, options:[\n  {v:'0', l:'Nessun impegno', mid:0},{v:'u5', l:'Meno di 5 anni', mid:3},\n  {v:'a5_10', l:'5–10 anni', mid:7},{v:'a10_20', l:'10–20 anni', mid:15},\n  {v:'o20', l:'Oltre 20 anni', mid:25}]},\n\n// ---------- SEZIONE: OBIETTIVI (dettaglio solo percorso completo) ----------\n// L'obiettivo principale è chiesto nella sezione iniziale. Nel percorso\n// essenziale il capitale target viene stimato con default prudenti dichiarati.\n{id:'capitaleObiettivo', step:'obiettivi', type:'radio', label:'Quale capitale vorresti raggiungere per questo obiettivo (a fine piano)?', precise:true, unit:'€',\n visibleIf: function(){ return T2() && !isFI(); }, options:[\n  {v:'c1', l:'Meno di 25.000 €', mid:20000},{v:'c2', l:'25.000–50.000 €', mid:37500},\n  {v:'c3', l:'50.000–100.000 €', mid:75000},{v:'c4', l:'100.000–250.000 €', mid:175000},\n  {v:'c5', l:'250.000–500.000 €', mid:375000},{v:'c6', l:'Oltre 500.000 €', mid:650000}]},\n\n// ---------- SEZIONE: DECUMULO (percorso completo, obiettivi pensione/indipendenza) ----------\n{id:'etaObiettivo', step:'decumulo', type:'radio', label:'A che età vorresti iniziare a vivere (anche in parte) del tuo capitale?',\n visibleIf: function(){ return T2() && isFI(); }, options:[\n  {v:'u50', l:'Prima dei 50 anni', mid:48},{v:'50_55', l:'50–55 anni', mid:53},\n  {v:'55_60', l:'55–60 anni', mid:58},{v:'60_67', l:'60–67 anni', mid:64},\n  {v:'67p', l:'Dopo i 67 anni', mid:68}]},\n{id:'speseTarget', step:'decumulo', type:'radio', label:'Che tenore di vita mensile vorresti in quella fase (in euro di oggi)?', precise:true, unit:'€/mese',\n visibleIf: function(){ return T2() && isFI(); }, options:[\n  {v:'st1', l:'Meno di 1.500 €', mid:1200},{v:'st2', l:'1.500–2.500 €', mid:2000},\n  {v:'st3', l:'2.500–4.000 €', mid:3200},{v:'st4', l:'Oltre 4.000 €', mid:5000}]},\n{id:'altreEntrateFuture', step:'decumulo', type:'radio', label:'Su quali altre entrate mensili potrai contare in quella fase (pensione pubblica, affitti…)?', precise:true, unit:'€/mese',\n visibleIf: function(){ return T2() && isFI(); },\n help:'Il capitale necessario copre solo la differenza tra il tenore di vita desiderato e queste entrate.', options:[\n  {v:'0', l:'Nessuna o quasi', mid:0},{v:'ae1', l:'Meno di 500 €', mid:300},\n  {v:'ae2', l:'500–1.000 €', mid:750},{v:'ae3', l:'1.000–2.000 €', mid:1500},\n  {v:'ae4', l:'Oltre 2.000 €', mid:2500}]},\n\n// ---------- SEZIONE: RISCHIO ----------\n{id:'conoscenza', step:'rischio', type:'radio', label:'Come valuti la tua conoscenza finanziaria?', visibleIf: T2, options:[\n  {v:'base', l:'Base: conosco conti e depositi', score:0},\n  {v:'media', l:'Media: so cosa sono fondi e obbligazioni', score:1},\n  {v:'buona', l:'Buona: conosco ETF, azioni e diversificazione', score:2},\n  {v:'avanzata', l:'Avanzata: valuto rischio, costi e asset allocation', score:3}]},\n{id:'esperienza', step:'rischio', type:'radio', label:'Che esperienza di investimento hai?', visibleIf: T2, options:[\n  {v:'nessuna', l:'Nessuna', score:0},\n  {v:'depositi', l:'Solo depositi, buoni o obbligazioni', score:1},\n  {v:'fondi', l:'Fondi comuni o ETF', score:2},\n  {v:'azioni', l:'Azioni singole o strumenti complessi', score:3}]},\n{id:'reazione', step:'rischio', type:'radio', label:'Il tuo portafoglio perde il 20% in pochi mesi. Cosa fai?', options:[\n  {v:'vendo_tutto', l:'Vendo tutto per evitare altre perdite', score:0},\n  {v:'vendo_parte', l:'Vendo una parte', score:1},\n  {v:'mantengo', l:'Mantengo le posizioni e aspetto', score:2},\n  {v:'compro', l:'Ne approfitto per investire di più', score:3}]},\n{id:'perditaMax', step:'rischio', type:'radio', label:'Qual è la perdita temporanea massima che potresti tollerare senza vendere?', options:[\n  {v:'p5', l:'Circa 5%', score:0, maxdd:5},\n  {v:'p10', l:'Circa 10%', score:1, maxdd:10},\n  {v:'p20', l:'Circa 20%', score:2, maxdd:20},\n  {v:'p30', l:'30% o più', score:3, maxdd:30}]},\n{id:'priorita', step:'rischio', type:'radio', label:'Tra stabilità e rendimento, cosa conta di più per te?', visibleIf: T3,\n options:[\n  {v:'protezione', l:'Protezione: preferisco stabilità anche con rendimenti bassi', score:0},\n  {v:'equilibrio', l:'Equilibrio: un po’ di crescita accettando oscillazioni moderate', score:1.5},\n  {v:'crescita', l:'Crescita: accetto oscillazioni ampie per rendimenti maggiori', score:3}]},\n\n// ---------- STEP 8: ASSICURAZIONI ----------\n{id:'coperture', step:'assicurazioni', type:'multi', label:'Quali coperture assicurative hai già attive?',\n help:'Considera solo polizze personali/familiari in vigore. Seleziona tutte quelle presenti.', options:[\n  {v:'tcm', l:'Vita caso morte (TCM)'},\n  {v:'invalidita', l:'Invalidità permanente (da malattia o infortunio)'},\n  {v:'infortuni', l:'Infortuni'},\n  {v:'sanitaria', l:'Sanitaria / rimborso spese mediche'},\n  {v:'ltc', l:'LTC / non autosufficienza'},\n  {v:'rc', l:'Responsabilità civile della famiglia'},\n  {v:'abitazione', l:'Abitazione (incendio, danni)'},\n  {v:'tutela', l:'Tutela legale personale/familiare'},\n  {v:'mutuoprot', l:'Protezione mutuo/prestiti (CPI)'},\n  {v:'nessuna', l:'Nessuna copertura', exclusive:true}]}\n];\n\n/* ============================================================\n   STATO E UTILITY\n   ============================================================ */\nlet A = {};              // risposte: A[id] = valore (o array per multi)\nlet currentStep = 0;     // indice in STEPS\n\nconst byId = id => document.getElementById(id);\nconst Q = id => QUESTIONS.find(q => q.id === id);\nconst optOf = (id, v) => { const q = Q(id); return q ? (q.options.find(o => o.v === v) || null) : null; };\n\n// Valore numerico di una risposta: campo preciso (se inserito) o valore centrale del range\nfunction midVal(id){\n  const p = A[id + '_precise'];\n  if (p !== undefined && p !== null && p !== '' && !isNaN(+p) && +p >= 0) return +p;\n  const o = optOf(id, A[id]);\n  return o && typeof o.mid === 'number' ? o.mid : 0;\n}\nfunction scoreVal(id){ const o = optOf(id, A[id]); return o && typeof o.score === 'number' ? o.score : 0; }\nfunction labelOf(id){\n  const q = Q(id); if (!q) return '—';\n  if (q.type === 'multi'){\n    const arr = A[id] || [];\n    if (!arr.length) return '—';\n    return arr.map(v => (optOf(id, v) || {l:v}).l).join(', ');\n  }\n  const o = optOf(id, A[id]);\n  const p = A[id + '_precise'];\n  const hasP = p !== undefined && p !== '' && !isNaN(+p);\n  if (!o) return hasP ? fmtEUR(+p) + ' (valore preciso)' : '—'; // valido anche solo il valore preciso\n  let s = o.l;\n  if (hasP) s += ' (preciso: ' + fmtEUR(+p) + ')';\n  return s;\n}\nfunction fmtEUR(n){\n  if (n === null || n === undefined || isNaN(n)) return '—';\n  return new Intl.NumberFormat('it-IT', {style:'currency', currency:'EUR', maximumFractionDigits:0}).format(n);\n}\nfunction fmtPct(n, dec){ return (isNaN(n) ? '—' : n.toFixed(dec === undefined ? 1 : dec).replace('.', ',') + '%'); }\nfunction esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }\n\n/* ============================================================\n   WIZARD: RENDERING E NAVIGAZIONE\n   ============================================================ */\nfunction startWizard(){\n  byId('intro').hidden = true;\n  byId('wizard').hidden = false;\n  currentStep = 0;\n  renderStep();\n  window.scrollTo(0, 0);\n}\n\n// Una domanda è visibile se non ha condizione o la condizione è vera\nfunction isVisible(q){ return !q.visibleIf || q.visibleIf(); }\nfunction visibleQuestions(){ return QUESTIONS.filter(isVisible); }\n\n// Una domanda è considerata risposta anche se è stato inserito SOLO\n// il valore preciso, senza selezionare un range\nfunction hasPrecise(q){\n  if (!q.precise) return false;\n  const p = A[q.id + '_precise'];\n  return p !== undefined && p !== '' && !isNaN(+p);\n}\nfunction isAnswered(q){\n  if (q.type === 'multi') return !!(A[q.id] && A[q.id].length);\n  if (A[q.id] !== undefined && A[q.id] !== '') return true;\n  return hasPrecise(q);\n}\n\nfunction questionsForStep(stepId){\n  const s = STEPS.find(x => x.id === stepId);\n  if (!s || !s.sections || !s.sections.length) return [];\n  return QUESTIONS.filter(q => s.sections.includes(q.step) && isVisible(q));\n}\nfunction pageOfSection(sec){ return STEPS.findIndex(s => (s.sections || []).includes(sec)); }\nfunction answeredCount(){ return visibleQuestions().filter(isAnswered).length; }\n\nfunction updateCounter(){\n  const tot = visibleQuestions().length, done = answeredCount();\n  const el = byId('qCounter');\n  if (el) el.textContent = done + ' / ' + tot + ' domande · ne mancano ' + Math.max(0, tot - done);\n}\n\n// Auto-compilazione impegni finanziari in base alla domanda \"porta\"\nfunction normalizeDebts(){\n  const td = A.tipiDebiti || [];\n  const none = !td.length || td.includes('nessuno');\n  if (none){\n    A.mutuo = '0'; A.altriDebitiTot = '0'; A.rataMensile = '0'; A.durataImpegni = '0';\n    A.mutuo_precise = ''; A.altriDebitiTot_precise = ''; A.rataMensile_precise = '';\n    A._debtsAuto = true;\n  } else {\n    // se prima era tutto auto-compilato a zero, richiedi di nuovo i dati ora rilevanti\n    if (A._debtsAuto){ A.rataMensile = undefined; A.durataImpegni = undefined; A._debtsAuto = false; }\n    if (!td.includes('mutuo')){ A.mutuo = '0'; A.mutuo_precise = ''; }\n    else if (A.mutuo === '0' && !hasPrecise(Q('mutuo'))){ A.mutuo = undefined; }\n    const others = td.some(v => ['prestiti','auto','leasing','revolving','altri'].includes(v));\n    if (!others){ A.altriDebitiTot = '0'; A.altriDebitiTot_precise = ''; }\n    else if (A.altriDebitiTot === '0' && !hasPrecise(Q('altriDebitiTot'))){ A.altriDebitiTot = undefined; }\n  }\n}\n\n// Corpo di una pagina: sezioni tematiche con intestazione + domande visibili\nfunction renderStepBody(stepId){\n  const s = STEPS.find(x => x.id === stepId);\n  let html = '';\n  (s.sections || []).forEach(sec => {\n    const qs = QUESTIONS.filter(q => q.step === sec && isVisible(q));\n    if (!qs.length) return;\n    html += '<h3 style=\"margin:24px 0 2px;color:var(--brand);border-bottom:2px solid var(--line);padding-bottom:6px\">' +\n      esc(SECTION_TITLES[sec] || sec) + '</h3>' + qs.map(renderQuestion).join('');\n  });\n  // Disclaimer dinamico: percorso Light = analisi più imprecisa\n  if (stepId === 'p0' && A.approfondimento === 'light')\n    html += '<div class=\"alert warn\">⚠️ <div><b>Hai scelto il percorso Light.</b> L’analisi sarà più imprecisa: diversi dati (debiti residui, dettaglio patrimoniale, profilo di rischio) verranno stimati con ipotesi standard invece che con le tue risposte. Per decisioni importanti consigliamo il percorso Approfondito.</div></div>';\n  return html;\n}\n\nfunction renderStep(){\n  const step = STEPS[currentStep];\n  byId('stepTitle').textContent = step.title;\n  updateCounter();\n  updateXPBar();\n  byId('progressBarInner').style.width = Math.round(100 * currentStep / (STEPS.length - 1)) + '%';\n\n  // chips degli step\n  byId('stepChips').innerHTML = STEPS.map((s, i) =>\n    '<span class=\"stepchip ' + (i === currentStep ? 'active' : (i < currentStep ? 'done' : '')) + '\">' + esc(s.title) + '</span>'\n  ).join('');\n\n  const body = byId('stepBody');\n  if (step.id === 'riepilogo'){ body.innerHTML = renderRecap(); }\n  else if (step.id === 'risultati'){ /* gestito da showResults() */ }\n  else { body.innerHTML = renderStepBody(step.id); }\n\n  byId('btnPrev').disabled = currentStep === 0;\n  byId('btnNext').textContent = step.id === 'riepilogo' ? '📊 Genera l’analisi' : 'Avanti →';\n}\n\nfunction renderQuestion(q){\n  // Nessun handler inline: gli eventi sono gestiti tramite delegazione (compatibile iOS/Quick Look)\n  let inner = '';\n  if (q.type === 'select'){\n    inner = '<select class=\"fsel\" data-q=\"' + q.id + '\">' +\n      '<option value=\"\">— Seleziona —</option>' +\n      q.options.map(o => '<option value=\"' + o.v + '\"' + (A[q.id] === o.v ? ' selected' : '') + '>' + esc(o.l) + '</option>').join('') +\n      '</select>';\n  } else if (q.type === 'multi'){\n    const cur = A[q.id] || [];\n    inner = '<div class=\"opts\">' + q.options.map(o =>\n      '<label class=\"opt' + (cur.includes(o.v) ? ' checked' : '') + '\">' +\n      '<input type=\"checkbox\" data-q=\"' + q.id + '\" data-v=\"' + o.v + '\" ' + (cur.includes(o.v) ? 'checked' : '') +\n      '> ' + esc(o.l) + '</label>'\n    ).join('') + '</div>';\n  } else { // radio\n    inner = '<div class=\"opts\">' + q.options.map(o =>\n      '<label class=\"opt' + (A[q.id] === o.v ? ' checked' : '') + '\">' +\n      '<input type=\"radio\" name=\"' + q.id + '\" value=\"' + o.v + '\" data-q=\"' + q.id + '\" ' + (A[q.id] === o.v ? 'checked' : '') +\n      '> ' + esc(o.l) + '</label>'\n    ).join('') + '</div>';\n  }\n  if (q.precise){\n    const pv = A[q.id + '_precise'];\n    inner += '<div class=\"precise\"><input type=\"number\" min=\"0\" step=\"1\" inputmode=\"numeric\" placeholder=\"Valore preciso (opzionale)\"' +\n      ' value=\"' + (pv !== undefined && pv !== '' ? pv : '') + '\"' +\n      ' data-precise=\"' + q.id + '\"><span>' + esc(q.unit || '€') + ' — se lo inserisci, i calcoli useranno questo valore</span></div>';\n  }\n  return '<div class=\"q\" id=\"q_' + q.id + '\"><label class=\"qlabel\">' + esc(q.label) + '</label>' +\n    (q.help ? '<div class=\"qhelp\">' + esc(q.help) + '</div>' : '') + inner + '</div>';\n}\n\n// --- gestori risposta (richiamati dalla event delegation) ---\nfunction setAnswer(id, v){\n  A[id] = v;\n  award('q_' + id, 10, 'risposta registrata');\n  const pi = pageOfSection(Q(id).step);\n  if (currentStep === pi){ // ridisegna per evidenziare la scelta\n    byId('stepBody').innerHTML = renderStepBody(STEPS[pi].id);\n    updateCounter();\n  }\n}\nfunction setPrecise(id, v){\n  A[id + '_precise'] = v === '' ? '' : Math.max(0, +v);\n  if (v !== '') award('p_' + id, 5, 'valore preciso: analisi più accurata');\n  // il valore preciso rende valida la domanda anche senza range selezionato\n  const el = byId('q_' + id);\n  if (el && v !== '') el.classList.remove('q-missing');\n  updateCounter();\n}\nfunction toggleMulti(id, v, checked){\n  let cur = (A[id] || []).slice();\n  const isExclusive = (optOf(id, v) || {}).exclusive;\n  if (checked){\n    if (isExclusive) cur = [v];\n    else { cur = cur.filter(x => !(optOf(id, x) || {}).exclusive); cur.push(v); }\n  } else cur = cur.filter(x => x !== v);\n  A[id] = cur;\n  if (cur.length) award('q_' + id, 10, 'risposta registrata');\n  if (id === 'tipiDebiti') normalizeDebts(); // auto-compila/azzera le altre domande sui debiti\n  const pi = pageOfSection(Q(id).step);\n  if (currentStep === pi){\n    byId('stepBody').innerHTML = renderStepBody(STEPS[pi].id);\n    updateCounter();\n  }\n}\n\n// --- validazione step corrente (solo domande visibili; il valore preciso vale come risposta) ---\nfunction validateAnswers(stepId){\n  const missing = questionsForStep(stepId).filter(q => !isAnswered(q));\n  missing.forEach(q => { const el = byId('q_' + q.id); if (el) el.classList.add('q-missing'); });\n  if (missing.length){\n    const first = byId('q_' + missing[0].id);\n    if (first && first.scrollIntoView) first.scrollIntoView(true);\n  }\n  return missing.length === 0;\n}\n\nfunction nextStep(){\n  const step = STEPS[currentStep];\n  if (step.id !== 'riepilogo' && step.id !== 'risultati' && !validateAnswers(step.id)) return;\n  if (step.id === 'riepilogo'){ showResults(); return; }\n  if (step.sections && step.sections.length) award('page_' + step.id, 25, '„' + step.title + '” completata!');\n  currentStep = Math.min(currentStep + 1, STEPS.length - 1);\n  renderStep();\n  window.scrollTo(0, 0);\n}\nfunction prevStep(){\n  if (byId('results').hidden === false){ // torna dal report al riepilogo\n    byId('results').hidden = true; byId('wizard').hidden = false;\n    currentStep = STEPS.findIndex(s => s.id === 'riepilogo');\n  } else currentStep = Math.max(currentStep - 1, 0);\n  renderStep();\n  window.scrollTo(0, 0);\n}\nfunction gotoStep(i){ currentStep = i; byId('results').hidden = true; byId('wizard').hidden = false; renderStep(); window.scrollTo(0, 0); }\n// Riavvio con doppio tocco di conferma (niente confirm(): su iOS può essere bloccato)\nlet restartArmed = false;\nfunction restart(){\n  const btn = byId('btnRestart');\n  if (!restartArmed){\n    restartArmed = true;\n    if (btn) btn.textContent = '⚠️ Confermi? Tocca di nuovo per cancellare tutto';\n    setTimeout(() => { restartArmed = false; if (btn) btn.textContent = '↺ Ricomincia'; }, 4000);\n    return;\n  }\n  restartArmed = false;\n  A = {}; GAME.xp = 0; GAME.rewarded = {};\n  byId('results').hidden = true; byId('intro').hidden = false; window.scrollTo(0, 0);\n}\n\n/* ============================================================\n   GAMIFICATION (facoltativa — principi: amplificare motivazioni\n   reali, apprendimento prima di tutto, partecipazione volontaria)\n   Punti e trofei sono legati alla qualità dei dati e alla salute\n   finanziaria effettiva, mai a comportamenti fittizi.\n   ============================================================ */\nconst GAME = { enabled:true, xp:0, rewarded:{} };\nconst LEVELS = [\n  {min:0,   name:'🌱 Apprendista del patrimonio'},\n  {min:100, name:'📘 Pianificatore'},\n  {min:220, name:'🧭 Stratega finanziario'},\n  {min:360, name:'🏛️ CFO di famiglia'}\n];\nfunction gameLevel(){\n  let cur = LEVELS[0], next = null;\n  for (let i = 0; i < LEVELS.length; i++){\n    if (GAME.xp >= LEVELS[i].min) cur = LEVELS[i];\n    else { next = LEVELS[i]; break; }\n  }\n  return { cur, next };\n}\nfunction updateXPBar(){\n  const w = byId('xpWrap'); if (!w) return;\n  w.hidden = !GAME.enabled;\n  if (!GAME.enabled) return;\n  const { cur, next } = gameLevel();\n  const from = cur.min, to = next ? next.min : Math.max(GAME.xp, cur.min + 1);\n  byId('xpBar').style.width = Math.min(100, Math.round(100 * (GAME.xp - from) / Math.max(1, to - from))) + '%';\n  byId('xpLevel').textContent = cur.name;\n  byId('xpPts').textContent = GAME.xp + ' punti' + (next ? ' · prossimo livello a ' + next.min : ' · livello massimo!');\n}\nfunction toast(msg){\n  if (!GAME.enabled) return;\n  let wrap = document.querySelector('.toast-wrap');\n  if (!wrap){ wrap = document.createElement('div'); wrap.className = 'toast-wrap'; document.body.appendChild(wrap); }\n  const t = document.createElement('div');\n  t.className = 'toast'; t.textContent = msg;\n  wrap.appendChild(t);\n  setTimeout(function(){ if (t.parentNode) t.parentNode.removeChild(t); }, 3000);\n}\n// premio una-tantum: ogni chiave viene pagata una sola volta\nfunction award(key, pts, label){\n  if (!GAME.enabled || GAME.rewarded[key]) return;\n  GAME.rewarded[key] = true;\n  GAME.xp += pts;\n  toast('+' + pts + ' punti · ' + label);\n  updateXPBar();\n}\nfunction confettiBurst(){\n  if (!GAME.enabled) return;\n  const colors = ['#1f4e79','#2e7dba','#0e8a6d','#d99a06','#8a5fbf','#d64545'];\n  for (let i = 0; i < 60; i++){\n    const c = document.createElement('span');\n    c.className = 'confetti';\n    c.style.left = Math.random() * 100 + 'vw';\n    c.style.background = colors[i % colors.length];\n    c.style.animationDuration = (2.2 + Math.random() * 2) + 's';\n    c.style.animationDelay = (Math.random() * .6) + 's';\n    document.body.appendChild(c);\n    setTimeout(function(){ if (c.parentNode) c.parentNode.removeChild(c); }, 5200);\n  }\n}\n\n// ---- Trofei: si sbloccano solo con comportamenti finanziari reali ----\nfunction generateBadges(M){\n  const preciseCount = QUESTIONS.filter(q => q.precise && A[q.id + '_precise'] !== undefined && A[q.id + '_precise'] !== '').length;\n  return [\n    {ic:'🛡️', name:'Guardiano', earned:M.ef.months >= 6, how:'Fondo di emergenza da almeno 6 mesi di spese', got:'La tua riserva copre 6+ mesi: le emergenze non ti spaventano.'},\n    {ic:'🐜', name:'Formica d’oro', earned:M.cf.savingsRate >= 0.15, how:'Tasso di risparmio di almeno il 15%', got:'Risparmi almeno il 15% del reddito: la base di ogni patrimonio.'},\n    {ic:'⛓️', name:'Spezza catene', earned:M.nw.totalDebt === 0 || M.debt.rateOnIncome <= 0.2, how:'Nessun debito, o rate sotto il 20% del reddito', got:'I debiti non comandano sul tuo bilancio.'},\n    {ic:'🎯', name:'Rotta tracciata', earned:M.goalGap <= 0, how:'Proiezione che raggiunge il tuo obiettivo', got:'Con le ipotesi prudenti attuali, il tuo obiettivo è a portata.'},\n    {ic:'🧊', name:'Mente fredda', earned:A.reazione === 'mantengo' || A.reazione === 'compro', how:'Disciplina dichiarata nei ribassi di mercato', got:'Nei cali non vendi: è il superpotere dell’investitore.'},\n    {ic:'🔬', name:'Analista', earned:M.tier === 3, how:'Completa il percorso Approfondito', got:'Hai scelto l’analisi più accurata.'},\n    {ic:'📐', name:'Precisione svizzera', earned:preciseCount >= 3, how:'Inserisci almeno 3 valori precisi', got:'Dati precisi = analisi più affidabile.'},\n    {ic:'👫', name:'Gioco di squadra', earned:!!M.couple, how:'Fai l’analisi di coppia', got:'Pianificare in due rende la famiglia più solida.'},\n    {ic:'☂️', name:'Ombrello aperto', earned:M.ins.red === 0 && (A.coperture || []).some(c => c !== 'nessuna'), how:'Nessuna protezione essenziale mancante', got:'I rischi gravi sono coperti: si costruisce solo su fondamenta protette.'}\n  ];\n}\nfunction renderBadges(M){\n  const badges = generateBadges(M);\n  const earned = badges.filter(b => b.earned).length;\n  return '<p class=\"muted small\">Trofei sbloccati: <b>' + earned + ' su ' + badges.length + '</b>. Quelli in grigio ti dicono già su cosa lavorare.</p><div class=\"badge-grid\">' +\n    badges.map(b => '<div class=\"badge-card' + (b.earned ? '' : ' locked') + '\"><div class=\"bic\">' + b.ic + '</div><b>' + esc(b.name) + '</b><p>' + esc(b.earned ? b.got : 'Come sbloccarlo: ' + b.how) + '</p></div>').join('') + '</div>';\n}\n\n// ---- Missioni: sfide concrete generate dalle aree deboli reali ----\nfunction generateMissions(M){\n  const ms = [];\n  if (M.ef.months < 6) ms.push({ic:'🛡️', t:'Missione Scudo', d:'Porta il fondo di emergenza a 6 mesi di spese: mancano circa ' + fmtEUR(M.ef.gap) + '. Versali su un conto separato e non toccarli.', pts:100});\n  if (M.debt.hasRevolving) ms.push({ic:'✂️', t:'Missione Forbici', d:'Estingui le carte revolving: nessun investimento prudente rende quanto costano.', pts:120});\n  if (M.debt.rateOnIncome > 0.35) ms.push({ic:'⚖️', t:'Missione Alleggerimento', d:'Riduci le rate sotto il 35% del reddito: rinegozia, consolida o estingui il debito più caro.', pts:100});\n  if (M.ins.red > 0) ms.push({ic:'☂️', t:'Missione Ombrello', d:'Chiudi le ' + M.ins.red + ' lacune assicurative critiche segnalate: proteggere i rischi gravi viene prima di investire.', pts:100});\n  if (M.cf.savingsRate < 0.15 && M.cf.implicitSavings > 0) ms.push({ic:'🐜', t:'Missione +50', d:'Aumenta il risparmio di 50 €/mese (automatizzalo il giorno dello stipendio) e punta al 15% del reddito.', pts:80});\n  if (M.risk.warnings.length) ms.push({ic:'🧭', t:'Missione Bussola', d:'Chiarisci con un consulente le incoerenze del tuo profilo di rischio prima di cambiare gli investimenti.', pts:60});\n  if (M.tier === 1) ms.push({ic:'🔬', t:'Missione Lente', d:'Rifai l’analisi con il percorso Approfondito per una fotografia molto più accurata.', pts:60});\n  if (!ms.length) ms.push({ic:'🏆', t:'Missione Mantenimento', d:'Le basi sono solide! Rivedi il piano tra 12 mesi o dopo eventi importanti (casa, figli, lavoro) e difendi il tuo indice.', pts:50});\n  return ms;\n}\nfunction renderMissions(M, score){\n  return generateMissions(M).map(m =>\n    '<div class=\"mission\"><span class=\"mic\">' + m.ic + '</span><div><b>' + esc(m.t) + '</b><p>' + esc(m.d) + '</p></div><span class=\"mpts\">+' + m.pts + ' pt</span></div>'\n  ).join('') + '<div class=\"alert info\">🔁 <div><b>Sfida con te stesso:</b> salva il report di oggi (indice ' + score + '/100), completa una missione nella vita reale e rifai l’analisi tra qualche mese. Battere il proprio punteggio è l’unica classifica che conta.</div></div>';\n}\n\n// ---- Indice di salute finanziaria 0–100 (dai semafori) ----\nfunction computeHealthScore(lights){\n  const pts = lights.reduce((s, l) => s + (l.level === 'g' ? 10 : (l.level === 'y' ? 5 : 0)), 0);\n  return Math.round(100 * pts / (lights.length * 10));\n}\n\n// --- riepilogo dati inseriti (collectAnswers) ---\nfunction collectAnswers(){\n  return QUESTIONS.map(q => ({id:q.id, step:q.step, label:q.label, value:labelOf(q.id)}));\n}\nfunction renderRecap(){\n  let html = '<p class=\"muted\">Controlla le risposte. Puoi tornare a qualsiasi pagina per correggerle.</p>';\n  STEPS.slice(0, 4).forEach((s, si) => {\n    html += '<h3 style=\"margin-top:20px;color:var(--brand)\">' + esc(s.title) +\n      ' <a style=\"font-size:.78rem;cursor:pointer;text-decoration:underline;color:var(--brand-2)\" data-goto=\"' + si + '\">modifica</a></h3>';\n    s.sections.forEach(sec => {\n      const qs = QUESTIONS.filter(q => q.step === sec && isVisible(q));\n      if (!qs.length) return;\n      html += '<div class=\"muted small\" style=\"margin-top:10px;font-weight:700\">' + esc(SECTION_TITLES[sec] || sec) + '</div>';\n      html += qs.map(q =>\n        '<div class=\"rec-row\"><span class=\"rl\">' + esc(q.label) + '</span><span class=\"rv\">' + esc(labelOf(q.id)) + '</span></div>'\n      ).join('');\n    });\n  });\n  return html;\n}\n/* ============================================================\n   MOTORE DI CALCOLO\n   Ipotesi dichiarate (nominali, prudenti, al lordo di inflazione):\n   - Conservativo: 2,0% annuo · Bilanciato: 3,2% · Dinamico: 4,5%\n   - Scenario prudente: base −1,5 punti · positivo: base +1,5 punti\n   - Costi/tasse non modellati in dettaglio (v. sezione limiti)\n   ============================================================ */\n\nconst RETURNS = { conservativo:0.020, bilanciato:0.032, dinamico:0.045 };\nconst SCENARIO_DELTA = 0.015;\n\n// ---- Patrimonio ----\nfunction calculateNetWorth(){\n  const liq = midVal('liquidita'), inv = midVal('investimenti'), imm = midVal('immobili'),\n        prev = midVal('previdenza'), altri = midVal('altriAsset');\n  const grossAssets = liq + inv + imm + prev + altri;\n  let mutuo, altriDeb, totalDebt, debtEstimated = false;\n  const td = A.tipiDebiti || [];\n  const hasDebts = td.length > 0 && !td.includes('nessuno');\n  if (deepMode() || !hasDebts){\n    mutuo = midVal('mutuo'); altriDeb = midVal('altriDebitiTot');\n    totalDebt = mutuo + altriDeb;\n  } else {\n    // Percorso essenziale: il debito residuo è stimato dalla rata\n    // (ipotesi dichiarata: durata media residua 5 anni)\n    totalDebt = Math.round(midVal('rataMensile') * 12 * 5);\n    mutuo = td.includes('mutuo') ? Math.round(totalDebt * 0.8) : 0;\n    altriDeb = totalDebt - mutuo;\n    debtEstimated = true;\n  }\n  return { liq, inv, imm, prev, altri, grossAssets, mutuo, altriDeb, totalDebt, debtEstimated, netWorth: grossAssets - totalDebt };\n}\n\n// ---- Fiscalità (stime semplificate, dichiarate nelle assunzioni) ----\n// 26% sui guadagni della maggior parte degli strumenti, 12,5% titoli di Stato,\n// 20% come proxy per portafogli misti. Bollo 0,2% annuo sul conto titoli.\nfunction effTaxRate(){\n  const map = { deposito:0.26, titoli_stato:0.125, fondi:0.26, azioni:0.26, misto:0.20 };\n  return map[A.tipoStrumenti] !== undefined ? map[A.tipoStrumenti] : 0.26;\n}\n\n// ---- Capitale obiettivo: dichiarato, calcolato (indipendenza) o default prudente ----\nfunction computeGoal(cf, investable){\n  if (deepMode() && isFI() && isAnswered(Q('speseTarget'))){\n    // Regola del 4% (25× il fabbisogno) + correzione fiscale sul decumulo:\n    // si assume che ~50% di ogni prelievo sia rendimento tassato.\n    const needY = Math.max(0, (midVal('speseTarget') - midVal('altreEntrateFuture')) * 12);\n    const taxFactor = 1 + effTaxRate() * 0.5;\n    return { value: Math.round(needY * 25 * taxFactor),\n      label:'capitale per l’indipendenza: 25× il fabbisogno annuo non coperto da altre entrate (regola del 4%), maggiorato per la fiscalità stimata sul decumulo' };\n  }\n  if (deepMode() && !isFI() && isAnswered(Q('capitaleObiettivo')))\n    return { value: midVal('capitaleObiettivo'), label:'capitale obiettivo che hai dichiarato' };\n  // default prudenti e dichiarati per il percorso essenziale\n  const D = {\n    emergenza: { v: cf.expensesM * 6, l:'6 mesi di spese (fondo di emergenza pieno)' },\n    casa: { v: 60000, l:'anticipo tipico per un acquisto immobiliare (ipotesi standard 60.000 €)' },\n    figli: { v: 50000, l:'budget educativo indicativo per figlio (ipotesi standard 50.000 €)' },\n    protezione: { v: cf.expensesY, l:'12 mesi di spese come cuscinetto di protezione' },\n    crescita: { v: Math.max(50000, investable * 2), l:'raddoppio del capitale investibile attuale (ipotesi)' },\n    pensione: { v: Math.max(100000, cf.expensesY * 10), l:'10 anni di spese attuali (ipotesi semplificata)' },\n    rendita: { v: Math.max(250000, cf.expensesY * 25), l:'25 volte le spese annue attuali (regola del 4%)' }\n  };\n  const d = D[A.obiettivo] || D.crescita;\n  return { value: Math.round(d.v), label: d.l };\n}\n\n// ---- Analisi di coppia (solo se l'utente sceglie di includere il partner) ----\nfunction analyzeCouple(cf){\n  if (!coupleMode()) return null;\n  const share = (optOf('quotaReddito', A.quotaReddito) || { share:0.5 }).share;\n  const mine = Math.round(cf.income * share);\n  const theirs = cf.income - mine;\n  const resp = (A.responsabilitaPartner || []).filter(v => v !== 'nessuna');\n  const heavy = resp.some(v => ['snc','sas','sindaco'].includes(v));\n  const concentration = share >= 0.7 || share <= 0.3;   // reddito concentrato su una sola persona\n  const keyPerson = share >= 0.5 ? 'tu' : 'il tuo partner';\n  const respLabels = resp.map(v => (optOf('responsabilitaPartner', v) || { l:v }).l);\n  return { share, mine, theirs, resp, respLabels, heavy, concentration, keyPerson };\n}\n\n// ---- Cash flow ----\nfunction calculateCashFlow(){\n  const income = midVal('reddito');                       // annuo netto\n  const expensesM = midVal('spesaMensile');\n  const savingsM = midVal('risparmioMensile');\n  const expensesY = expensesM * 12, savingsY = savingsM * 12;\n  const savingsRate = income > 0 ? savingsY / income : 0;\n  // controllo coerenza: reddito - spese dovrebbe ≈ risparmio\n  const implicitSavings = income - expensesY;\n  const incoherent = Math.abs(implicitSavings - savingsY) > Math.max(6000, income * 0.25);\n  return { income, expensesM, expensesY, savingsM, savingsY, savingsRate, implicitSavings, incoherent };\n}\n\n// ---- Sostenibilità del debito ----\nfunction calculateDebtSustainability(nw, cf){\n  const rateM = midVal('rataMensile');\n  const rateY = rateM * 12;\n  const rateOnIncome = cf.income > 0 ? rateY / cf.income : 0;      // incidenza rate/reddito\n  const debtToIncome = cf.income > 0 ? nw.totalDebt / cf.income : 0;\n  const hasRevolving = (A.tipiDebiti || []).includes('revolving');\n  const yearsLeft = midVal('durataImpegni');\n  return { rateM, rateY, rateOnIncome, debtToIncome, hasRevolving, yearsLeft };\n}\n\n// ---- Fondo di emergenza ----\nfunction calculateEmergencyFund(nw, cf){\n  const months = cf.expensesM > 0 ? nw.liq / cf.expensesM : 0;   // mesi coperti dalla liquidità\n  const dedicated = A.fondoEmergenza;                             // percezione dichiarata\n  const target = 6 * cf.expensesM;                                // obiettivo prudente: 6 mesi\n  const gap = Math.max(0, target - nw.liq);\n  return { months, dedicated, target, gap };\n}\n\n// ---- Capitale investibile: investimenti + liquidità oltre 6 mesi di spese ----\nfunction calculateInvestable(nw, cf){\n  const buffer = 6 * cf.expensesM;\n  return nw.inv + Math.max(0, nw.liq - buffer);\n}\n\n// ---- Profilo di rischio ----\n// Usa i fattori disponibili nel percorso scelto (il percorso essenziale ne\n// chiede meno) mediandoli su scala comune, così i due percorsi sono comparabili.\nfunction determineRiskProfile(){\n  const hIdx = ['breve','medio','lungo','moltolungo'].indexOf(A.orizzonte); // 0..3\n  // priorità dichiarata (percorso completo) o derivata dall'obiettivo (essenziale)\n  const prio = A.priorita || ({ crescita:'crescita', rendita:'crescita', pensione:'equilibrio',\n    casa:'equilibrio', figli:'equilibrio', emergenza:'protezione', protezione:'protezione' }[A.obiettivo] || 'equilibrio');\n  const prioScore = { protezione:0, equilibrio:1.5, crescita:3 }[prio];\n\n  const factors = [];                       // ciascun fattore vale 0..3\n  if (A.conoscenza) factors.push(scoreVal('conoscenza'));\n  if (A.esperienza) factors.push(scoreVal('esperienza'));\n  if (A.reazione) factors.push(scoreVal('reazione'));\n  if (A.perditaMax) factors.push(scoreVal('perditaMax'));\n  factors.push(prioScore);\n  factors.push(Math.max(0, hIdx));\n  let score = (factors.reduce((s, x) => s + x, 0) / factors.length) * 6; // scala 0..18\n  const age = midVal('eta');\n  if (age >= 65) score -= 2; else if (age >= 55) score -= 1;\n\n  let profile = score <= 6 ? 'conservativo' : (score <= 11 ? 'bilanciato' : 'dinamico');\n\n  // vincoli prudenziali e incoerenze\n  const warnings = [];\n  const maxdd = (optOf('perditaMax', A.perditaMax) || {}).maxdd || 5;\n  if (A.orizzonte === 'breve' && profile !== 'conservativo'){\n    warnings.push('Orizzonte inferiore a 5 anni: il profilo è stato limitato a Conservativo per prudenza.');\n    profile = 'conservativo';\n  }\n  if (maxdd <= 5 && profile !== 'conservativo'){\n    warnings.push('Hai indicato una tolleranza massima alle perdite di circa il 5%: il profilo è stato limitato a Conservativo.');\n    profile = 'conservativo';\n  } else if (maxdd <= 10 && profile === 'dinamico'){\n    warnings.push('Tolleranza alle perdite intorno al 10%: il profilo Dinamico non è coerente ed è stato ridotto a Bilanciato.');\n    profile = 'bilanciato';\n  }\n  if (prio === 'crescita' && maxdd <= 10)\n    warnings.push('Incoerenza: l’obiettivo punta alla crescita ma tolleri perdite contenute. Meglio chiarire questo punto con un consulente.');\n  if (A.reazione === 'vendo_tutto' && prio !== 'protezione')\n    warnings.push('Attenzione comportamentale: vendere tutto durante un calo è il modo più comune di trasformare una perdita temporanea in una definitiva.');\n  if (A.conoscenza && scoreVal('conoscenza') === 0 && scoreVal('esperienza') === 3)\n    warnings.push('Esperienza su strumenti complessi con conoscenza di base: possibile eccesso di fiducia (overconfidence).');\n\n  return { score, profile, warnings, maxdd, age, hIdx, prio };\n}\n\n// ---- Allocazioni indicative (3 proposte) ----\nfunction generateAllocationProfiles(risk, ef){\n  // base prudente per ciascun profilo: [liquidità, obbligazioni, azioni globali, oro/real asset, previdenza]\n  const base = {\n    conservativo: {liq:15, bond:55, eq:20, gold:5, pens:5},\n    bilanciato:   {liq:10, bond:40, eq:35, gold:8, pens:7},\n    dinamico:     {liq:5,  bond:25, eq:55, gold:8, pens:7}\n  };\n  const age = midVal('eta');\n  const out = {};\n  ['conservativo','bilanciato','dinamico'].forEach(p => {\n    const a = Object.assign({}, base[p]);\n    // aggiustamenti prudenti\n    if (age >= 60){ const shift = Math.min(10, a.eq); a.eq -= shift; a.bond += shift; }          // età alta → meno azioni\n    if (A.orizzonte === 'moltolungo' && p !== 'conservativo'){ a.eq += 5; a.bond -= 5; }          // orizzonte lungo → più azioni\n    if (ef.months < 3){ const shift = Math.min(10, a.eq); a.liq += shift; a.eq -= shift; }        // poca liquidità → priorità riserva\n    out[p] = a;\n  });\n  return out;\n}\n\n// ---- Gap assicurativi ----\nfunction calculateInsuranceGaps(nw, cf, debt){\n  const cov = A.coperture || [];\n  const has = c => cov.includes(c);\n  const deps = midVal('dipendenti');\n  const hasPartnerNoIncome = coupleMode() && A.quotaReddito === 'solo_io';\n  const hasFamily = deps > 0 || hasPartner();\n  const worksForIncome = !['pensione','rendite'].includes(A.fonteReddito);\n  const age = midVal('eta');\n  const gaps = []; // {area, level:'r'|'y'|'g', why}\n\n  // TCM: essenziale se qualcuno dipende dal tuo reddito\n  if ((deps > 0 || hasPartnerNoIncome) && !has('tcm'))\n    gaps.push({area:'Vita caso morte (TCM)', level:'r', why:'Ci sono persone che dipendono dal tuo reddito ma manca una copertura in caso di decesso. Capitale indicativo di riferimento: 5–10 volte il reddito annuo (' + fmtEUR(cf.income*5) + '–' + fmtEUR(cf.income*10) + ').'});\n  else if (deps > 0 && has('tcm'))\n    gaps.push({area:'Vita caso morte (TCM)', level:'g', why:'Copertura presente. Verifica che il capitale sia adeguato a reddito e debiti residui.'});\n\n  // Invalidità: protegge la capacità di produrre reddito\n  if (worksForIncome && !has('invalidita'))\n    gaps.push({area:'Invalidità permanente', level: deps > 0 ? 'r' : 'y', why:'Il reddito da lavoro è il tuo principale \"asset\": un’invalidità grave lo interromperebbe. È spesso il rischio più sottovalutato.'});\n  else if (worksForIncome)\n    gaps.push({area:'Invalidità permanente', level:'g', why:'Copertura presente.'});\n\n  // Infortuni\n  if (worksForIncome && !has('infortuni') && !has('invalidita'))\n    gaps.push({area:'Infortuni', level:'y', why:'Nessuna protezione per infortuni con conseguenze economiche.'});\n\n  // Sanitaria\n  gaps.push(has('sanitaria')\n    ? {area:'Sanitaria', level:'g', why:'Copertura presente.'}\n    : {area:'Sanitaria', level:'y', why:'Grandi interventi o cure lunghe possono pesare sul patrimonio. Da valutare in base a regione e esigenze familiari.'});\n\n  // LTC (rilevante crescendo con l'età)\n  if (age >= 50)\n    gaps.push(has('ltc')\n      ? {area:'LTC / non autosufficienza', level:'g', why:'Copertura presente.'}\n      : {area:'LTC / non autosufficienza', level:'y', why:'Dopo i 50 anni conviene valutare il rischio di non autosufficienza: i costi assistenziali possono erodere il patrimonio.'});\n\n  // RC famiglia: costo basso, rischio potenzialmente enorme\n  if (hasFamily && !has('rc'))\n    gaps.push({area:'RC famiglia', level:'y', why:'Un danno causato a terzi (anche dai figli) può generare richieste molto elevate. Copertura di norma poco costosa.'});\n  else if (has('rc'))\n    gaps.push({area:'RC famiglia', level:'g', why:'Copertura presente.'});\n\n  // Abitazione\n  if (nw.imm > 0)\n    gaps.push(has('abitazione')\n      ? {area:'Abitazione', level:'g', why:'Copertura presente.'}\n      : {area:'Abitazione', level:'y', why:'Possiedi immobili senza copertura per incendio/danni: un evento grave colpirebbe l’asset più grande.'});\n\n  // Protezione mutuo\n  if (nw.mutuo > 0 && !has('mutuoprot') && !has('tcm'))\n    gaps.push({area:'Protezione mutuo', level:'y', why:'Mutuo in corso senza TCM né polizza dedicata: in caso di evento grave il debito resterebbe alla famiglia.'});\n\n  // Tutela legale\n  if (!has('tutela'))\n    gaps.push({area:'Tutela legale', level:'y', why:'Copertura accessoria da valutare: aiuta a sostenere spese legali impreviste.'});\n\n  // Responsabilità personale qualificata (utente)\n  const resp = (A.responsabilita || []).filter(v => v !== 'nessuna');\n  if (resp.length){\n    const heavy = resp.some(v => ['snc','sas','sindaco'].includes(v));\n    gaps.push({area:'Responsabilità personale qualificata', level: heavy ? 'r' : 'y',\n      why:'Ricopri ruoli che espongono il patrimonio personale (' + resp.map(v => (optOf('responsabilita', v)||{l:v}).l).join(', ') +\n      '). Serve una verifica specifica delle coperture di responsabilità personale/professionale con un professionista: questa analisi non copre l’ambito aziendale.'});\n  }\n\n  // Responsabilità professionale del partner (se analisi di coppia)\n  const respP = (A.responsabilitaPartner || []).filter(v => v !== 'nessuna');\n  if (coupleMode() && respP.length){\n    const heavyP = respP.some(v => ['snc','sas','sindaco'].includes(v));\n    gaps.push({area:'Responsabilità professionale del partner', level: heavyP ? 'r' : 'y',\n      why:'Il tuo partner ricopre ruoli che possono esporre il patrimonio familiare (' + respP.map(v => (optOf('responsabilitaPartner', v)||{l:v}).l).join(', ') +\n      '). Da verificare: coperture di responsabilità professionale del partner e regime patrimoniale della coppia (comunione o separazione dei beni).'});\n  }\n\n  const red = gaps.filter(g => g.level === 'r').length;\n  const yellow = gaps.filter(g => g.level === 'y').length;\n  return { gaps, red, yellow, covCount: cov.filter(c => c !== 'nessuna').length };\n}\n\n// ---- Proiezione patrimoniale (capitalizzazione mensile) ----\nfunction runProjection(P0, monthly, years, annualReturn){\n  const rm = annualReturn / 12;\n  let v = Math.max(0, P0);\n  const points = [v];\n  const months = Math.round(years * 12);\n  for (let m = 1; m <= months; m++){\n    v = v * (1 + rm) + monthly;\n    if (m % 12 === 0) points.push(v);\n  }\n  if (months % 12 !== 0) points.push(v);\n  return { final: v, points, contributed: Math.max(0, P0) + monthly * months };\n}\n\n/* ============================================================\n   VALUTAZIONE A SEMAFORO (10 aree)\n   ============================================================ */\nfunction computeTrafficLights(M){\n  const {nw, cf, debt, ef, risk, ins} = M;\n  const L = [];\n  const add = (name, level, why) => L.push({name, level, why});\n\n  // 1. Solidità patrimoniale\n  const nwRatio = cf.income > 0 ? nw.netWorth / cf.income : 0;\n  if (nw.netWorth < 0) add('Solidità patrimoniale', 'r', 'Il patrimonio netto è negativo: i debiti superano gli attivi.');\n  else if (nwRatio < 1) add('Solidità patrimoniale', 'y', 'Patrimonio netto inferiore a un anno di reddito: la base è ancora sottile.');\n  else if (nwRatio < 3) add('Solidità patrimoniale', 'y', 'Patrimonio netto pari a ' + nwRatio.toFixed(1).replace('.',',') + ' anni di reddito: in costruzione.');\n  else add('Solidità patrimoniale', 'g', 'Patrimonio netto pari a circa ' + nwRatio.toFixed(1).replace('.',',') + ' anni di reddito.');\n\n  // 2. Liquidità / fondo emergenza\n  if (ef.months >= 6) add('Liquidità / fondo emergenza', 'g', 'La liquidità copre circa ' + Math.round(ef.months) + ' mesi di spese.');\n  else if (ef.months >= 3) add('Liquidità / fondo emergenza', 'y', 'Copertura di circa ' + Math.round(ef.months) + ' mesi: l’obiettivo prudente è 6 mesi.');\n  else add('Liquidità / fondo emergenza', 'r', 'Meno di 3 mesi di spese coperte: priorità assoluta prima di investire.');\n\n  // 3. Sostenibilità cash flow\n  if (cf.implicitSavings < 0) add('Sostenibilità cash flow', 'r', 'Le spese stimate superano il reddito: il bilancio familiare è in deficit.');\n  else if (cf.savingsRate >= 0.15) add('Sostenibilità cash flow', 'g', 'Tasso di risparmio di circa ' + fmtPct(cf.savingsRate*100, 0) + ': ottima capacità di accumulo.');\n  else if (cf.savingsRate >= 0.05) add('Sostenibilità cash flow', 'y', 'Tasso di risparmio di circa ' + fmtPct(cf.savingsRate*100, 0) + ': margine di miglioramento.');\n  else add('Sostenibilità cash flow', 'r', 'Risparmio quasi nullo: senza accantonamenti il piano non può decollare.');\n\n  // 4. Impegni finanziari / debiti\n  if (debt.rateY === 0 && nw.totalDebt === 0) add('Impegni finanziari', 'g', 'Nessun debito in corso.');\n  else if (debt.hasRevolving) add('Impegni finanziari', 'r', 'Le carte revolving hanno costi molto elevati: estinguerle è di norma la priorità numero uno.');\n  else if (debt.rateOnIncome > 0.35) add('Impegni finanziari', 'r', 'Le rate assorbono circa ' + fmtPct(debt.rateOnIncome*100, 0) + ' del reddito: livello critico (soglia di attenzione: 35%).');\n  else if (debt.rateOnIncome > 0.20) add('Impegni finanziari', 'y', 'Rate pari a circa ' + fmtPct(debt.rateOnIncome*100, 0) + ' del reddito: sostenibile ma da monitorare.');\n  else add('Impegni finanziari', 'g', 'Rate pari a circa ' + fmtPct(debt.rateOnIncome*100, 0) + ' del reddito: incidenza contenuta.');\n\n  // 5. Coperture assicurative\n  if (ins.red > 0) add('Coperture assicurative', 'r', ins.red + ' protezione/i essenziale/i mancante/i (dettaglio nella sezione dedicata).');\n  else if (ins.yellow >= 3) add('Coperture assicurative', 'y', 'Diverse aree di protezione da valutare o completare.');\n  else add('Coperture assicurative', 'g', 'Le protezioni principali risultano presenti rispetto al tuo profilo.');\n\n  // 6. Coerenza investimenti / orizzonte\n  if (A.orizzonte === 'breve' && risk.profile !== 'conservativo') add('Coerenza investimenti / orizzonte', 'r', 'Orizzonte breve e profilo aggressivo non sono compatibili.');\n  else if (risk.hIdx >= 2 && nw.inv === 0 && cf.savingsY > 0 && ef.months >= 3) add('Coerenza investimenti / orizzonte', 'y', 'Orizzonte lungo, buona capacità di risparmio ma nessun investimento: il capitale fermo perde potere d’acquisto con l’inflazione.');\n  else add('Coerenza investimenti / orizzonte', 'g', 'Orizzonte e impostazione appaiono coerenti.');\n\n  // 7. Propensione al rischio vs allocazione\n  if (risk.warnings.length >= 2) add('Propensione vs tolleranza al rischio', 'r', 'Più segnali di incoerenza tra rischio dichiarato e comportamento atteso.');\n  else if (risk.warnings.length === 1) add('Propensione vs tolleranza al rischio', 'y', risk.warnings[0]);\n  else add('Propensione vs tolleranza al rischio', 'g', 'Il profilo ' + risk.profile + ' appare coerente con le tue risposte.');\n\n  // 8. Rischio comportamentale\n  if (A.reazione === 'vendo_tutto') add('Rischio comportamentale', 'r', 'La reazione di panico nei cali è il principale distruttore di rendimento di lungo periodo.');\n  else if (A.reazione === 'vendo_parte' || (A.conoscenza && scoreVal('conoscenza') <= 1 && risk.profile === 'dinamico')) add('Rischio comportamentale', 'y', 'Nei momenti di stress potresti deviare dal piano: utile definire regole scritte in anticipo.');\n  else add('Rischio comportamentale', 'g', 'Atteggiamento dichiarato disciplinato nei ribassi.');\n\n  // 9. Protezione del nucleo familiare\n  const deps = midVal('dipendenti');\n  if (deps > 0 || (coupleMode() && A.quotaReddito === 'solo_io')){\n    const tcmOk = (A.coperture || []).includes('tcm'), invOk = (A.coperture || []).includes('invalidita');\n    if (!tcmOk && !invOk) add('Protezione del nucleo familiare', 'r', 'Persone a carico e nessuna protezione su decesso o invalidità di chi produce reddito.');\n    else if (!tcmOk || !invOk) add('Protezione del nucleo familiare', 'y', 'Protezione del nucleo parziale: manca ' + (!tcmOk ? 'la copertura caso morte' : 'la copertura invalidità') + '.');\n    else add('Protezione del nucleo familiare', 'g', 'Le protezioni chiave del nucleo risultano presenti.');\n  } else add('Protezione del nucleo familiare', 'g', 'Nessuna persona economicamente dipendente: l’esigenza di protezione del nucleo è limitata.');\n\n  // 10. Responsabilità civile personale qualificata (utente + eventuale partner)\n  const resp = (A.responsabilita || []).filter(v => v !== 'nessuna');\n  const respP = (A.responsabilitaPartner || []).filter(v => v !== 'nessuna');\n  const heavyRole = v => ['snc','sas','sindaco'].includes(v);\n  if (A.responsabilita === undefined && !coupleMode()) add('Responsabilità personale qualificata', 'y', 'Tema non incluso nel percorso Light. Se ricopri ruoli con responsabilità personali (professionista con albo, amministratore, socio SNC/SAS, sindaco/revisore), rifai l’analisi in modalità Standard o Approfondita.');\n  else if (!resp.length && !respP.length) add('Responsabilità personale qualificata', 'g', 'Nessun ruolo con esposizione patrimoniale particolare dichiarato' + (coupleMode() ? ', né per te né per il partner.' : '.'));\n  else if (resp.some(heavyRole) || respP.some(heavyRole)) add('Responsabilità personale qualificata', 'r', (resp.some(heavyRole) ? 'Ricopri ruoli' : 'Il tuo partner ricopre ruoli') + ' con responsabilità illimitata o molto elevata: necessaria verifica professionale specifica delle coperture e del regime patrimoniale.');\n  else add('Responsabilità personale qualificata', 'y', (resp.length && respP.length ? 'Tu e il tuo partner ricoprite' : (respP.length ? 'Il tuo partner ricopre' : 'Ricopri')) + ' ruoli con possibile esposizione personale: consigliata una verifica delle coperture di responsabilità con un professionista.');\n\n  return L;\n}\n\n/* ============================================================\n   MODELLO COMPLESSIVO\n   ============================================================ */\nfunction computeAll(){\n  normalizeDebts(); // garantisce coerenza delle risposte auto-compilate sui debiti\n  const nw = calculateNetWorth();\n  const cf = calculateCashFlow();\n  const debt = calculateDebtSustainability(nw, cf);\n  const ef = calculateEmergencyFund(nw, cf);\n  const investable = calculateInvestable(nw, cf);\n  const risk = determineRiskProfile();\n  const ins = calculateInsuranceGaps(nw, cf, debt);\n  const allocs = generateAllocationProfiles(risk, ef);\n\n  // obiettivo (dichiarato, calcolato per l'indipendenza, o default prudente)\n  const goalObj = computeGoal(cf, investable);\n  const goal = goalObj.value;\n\n  // orizzonte: dal piano dichiarato, oppure dall'età-obiettivo (indipendenza/pensione)\n  let years = midVal('orizzonte');\n  if (deepMode() && isFI() && A.etaObiettivo)\n    years = Math.min(40, Math.max(1, midVal('etaObiettivo') - midVal('eta')));\n\n  const baseR = RETURNS[risk.profile];\n  const monthly = cf.savingsM;\n  const projBase = runProjection(investable, monthly, years, baseR);\n  const projLow  = runProjection(investable, monthly, years, Math.max(0.005, baseR - SCENARIO_DELTA));\n  const projHigh = runProjection(investable, monthly, years, baseR + SCENARIO_DELTA);\n  const goalGap = goal - projBase.final;\n\n  // fiscalità stimata (v. assunzioni): imposta sui guadagni e bollo titoli\n  const tax = effTaxRate();\n  const growth = Math.max(0, projBase.final - projBase.contributed);\n  const netFinal = projBase.contributed + growth * (1 - tax);        // valore netto se liquidato a fine piano\n  const bolloStima = Math.round(0.002 * ((investable + projBase.final) / 2) * years); // 0,2% annuo sul saldo medio\n\n  // sostenibilità degli accantonamenti: il risparmio dichiarato è compatibile col bilancio?\n  const sustainable = cf.implicitSavings >= cf.savingsY * 0.8 || cf.savingsY === 0;\n\n  const couple = analyzeCouple(cf);\n\n  const M = { nw, cf, debt, ef, investable, risk, ins, allocs, goal, goalLabel: goalObj.label,\n              years, baseR, monthly, projBase, projLow, projHigh, goalGap, sustainable,\n              tax, growth, netFinal, bolloStima, deep: deepMode(), tier: tier(), tierLabel: tierName(), couple };\n  M.lights = computeTrafficLights(M);\n  return M;\n}\n/* ============================================================\n   GRAFICI SVG (vanilla, nessuna libreria)\n   ============================================================ */\nconst PALETTE = ['#1f4e79','#2e7dba','#0e8a6d','#d99a06','#8a5fbf','#d64545','#5a6b7d'];\n\nfunction polar(cx, cy, r, ang){ return [cx + r * Math.cos(ang), cy + r * Math.sin(ang)]; }\n\n// Donut chart: items = [{label, value, color}]\nfunction svgDonut(items, size){\n  size = size || 220;\n  const total = items.reduce((s, i) => s + i.value, 0);\n  if (total <= 0) return '<p class=\"muted small\" style=\"text-align:center\">Nessun dato da rappresentare.</p>';\n  const cx = size/2, cy = size/2, r1 = size/2 - 6, r2 = size/4.4;\n  let a = -Math.PI/2, paths = '';\n  items.filter(i => i.value > 0).forEach(i => {\n    const frac = i.value / total, a2 = a + frac * 2 * Math.PI;\n    const large = frac > 0.5 ? 1 : 0;\n    // settore quasi completo: disegna anello pieno\n    if (frac > 0.999){\n      paths += `<circle cx=\"${cx}\" cy=\"${cy}\" r=\"${(r1+r2)/2}\" fill=\"none\" stroke=\"${i.color}\" stroke-width=\"${r1-r2}\"/>`;\n    } else {\n      const [x1,y1] = polar(cx,cy,r1,a), [x2,y2] = polar(cx,cy,r1,a2);\n      const [x3,y3] = polar(cx,cy,r2,a2), [x4,y4] = polar(cx,cy,r2,a);\n      paths += `<path d=\"M${x1.toFixed(1)},${y1.toFixed(1)} A${r1},${r1} 0 ${large} 1 ${x2.toFixed(1)},${y2.toFixed(1)} L${x3.toFixed(1)},${y3.toFixed(1)} A${r2},${r2} 0 ${large} 0 ${x4.toFixed(1)},${y4.toFixed(1)} Z\" fill=\"${i.color}\" stroke=\"#fff\" stroke-width=\"1.5\"/>`;\n    }\n    a = a2;\n  });\n  const legend = '<div class=\"legend\">' + items.filter(i => i.value > 0).map(i =>\n    `<span><i style=\"background:${i.color}\"></i>${esc(i.label)} · ${fmtEUR(i.value)} (${fmtPct(100*i.value/total,0)})</span>`).join('') + '</div>';\n  return `<svg viewBox=\"0 0 ${size} ${size}\" width=\"${size}\" role=\"img\">${paths}</svg>` + legend;\n}\n\n// Line chart: series = [{name, color, points[]}] (punti annuali), hline opzionale = {value,label}\nfunction svgLines(series, hline, yearsLabel){\n  const w = 680, h = 300, padL = 78, padR = 16, padT = 16, padB = 34;\n  let maxV = 0, maxN = 0;\n  series.forEach(s => { maxN = Math.max(maxN, s.points.length - 1); s.points.forEach(p => maxV = Math.max(maxV, p)); });\n  if (hline) maxV = Math.max(maxV, hline.value);\n  maxV = maxV * 1.08 || 1;\n  const X = i => padL + (w - padL - padR) * (maxN ? i / maxN : 0);\n  const Y = v => padT + (h - padT - padB) * (1 - v / maxV);\n  let g = '';\n  for (let k = 0; k <= 4; k++){\n    const v = maxV * k / 4, y = Y(v);\n    g += `<line x1=\"${padL}\" y1=\"${y}\" x2=\"${w-padR}\" y2=\"${y}\" stroke=\"#e3e8ef\"/>` +\n         `<text x=\"${padL-8}\" y=\"${y+4}\" font-size=\"11\" fill=\"#5a6b7d\" text-anchor=\"end\">${fmtShort(v)}</text>`;\n  }\n  const step = Math.max(1, Math.ceil(maxN / 8));\n  for (let i = 0; i <= maxN; i += step)\n    g += `<text x=\"${X(i)}\" y=\"${h-10}\" font-size=\"11\" fill=\"#5a6b7d\" text-anchor=\"middle\">${i}</text>`;\n  g += `<text x=\"${(w+padL)/2}\" y=\"${h+2}\" font-size=\"10\" fill=\"#5a6b7d\" text-anchor=\"middle\">${esc(yearsLabel || 'anni')}</text>`;\n  series.forEach(s => {\n    const d = s.points.map((p, i) => (i ? 'L' : 'M') + X(i).toFixed(1) + ',' + Y(p).toFixed(1)).join(' ');\n    g += `<path d=\"${d}\" fill=\"none\" stroke=\"${s.color}\" stroke-width=\"2.5\" stroke-linejoin=\"round\"/>`;\n  });\n  if (hline){\n    g += `<line x1=\"${padL}\" y1=\"${Y(hline.value)}\" x2=\"${w-padR}\" y2=\"${Y(hline.value)}\" stroke=\"#d64545\" stroke-dasharray=\"6 4\" stroke-width=\"1.5\"/>` +\n         `<text x=\"${w-padR}\" y=\"${Y(hline.value)-6}\" font-size=\"11\" fill=\"#d64545\" text-anchor=\"end\">${esc(hline.label)}</text>`;\n  }\n  const legend = '<div class=\"legend\">' + series.map(s => `<span><i style=\"background:${s.color}\"></i>${esc(s.name)}</span>`).join('') +\n    (hline ? `<span><i style=\"background:#d64545\"></i>${esc(hline.label)}</span>` : '') + '</div>';\n  return `<div class=\"chart-box\"><svg viewBox=\"0 0 ${w} ${h+8}\" width=\"${w}\">${g}</svg>${legend}</div>`;\n}\nfunction fmtShort(v){\n  if (v >= 1e6) return (v/1e6).toFixed(1).replace('.',',') + ' M€';\n  if (v >= 1e3) return Math.round(v/1e3) + ' k€';\n  return Math.round(v) + ' €';\n}\n\n// Barre orizzontali: items = [{label, value, color, text}]\nfunction svgHBars(items, maxV){\n  const w = 680, rowH = 34, padL = 200, padR = 90, h = items.length * rowH + 10;\n  maxV = maxV || Math.max(1, ...items.map(i => i.value));\n  let g = '';\n  items.forEach((it, k) => {\n    const y = 8 + k * rowH, bw = Math.max(2, (w - padL - padR) * it.value / maxV);\n    g += `<text x=\"${padL-8}\" y=\"${y+15}\" font-size=\"12\" fill=\"#1c2733\" text-anchor=\"end\">${esc(trunc(it.label, 28))}</text>` +\n         `<rect x=\"${padL}\" y=\"${y}\" width=\"${bw}\" height=\"20\" rx=\"5\" fill=\"${it.color}\"/>` +\n         `<text x=\"${padL+bw+7}\" y=\"${y+15}\" font-size=\"12\" fill=\"#5a6b7d\">${esc(it.text !== undefined ? it.text : String(it.value))}</text>`;\n  });\n  return `<div class=\"chart-box\"><svg viewBox=\"0 0 ${w} ${h}\" width=\"${w}\">${g}</svg></div>`;\n}\nfunction trunc(s, n){ return s.length > n ? s.slice(0, n-1) + '…' : s; }\n\n// Barre impilate per confronto allocazioni\nfunction svgStacked(rows){ // rows = [{label, segments:[{value,color,name}]}]\n  const w = 680, rowH = 46, padL = 120, padR = 12, h = rows.length * rowH + 6;\n  let g = '';\n  rows.forEach((r, k) => {\n    const y = 6 + k * rowH;\n    g += `<text x=\"${padL-8}\" y=\"${y+20}\" font-size=\"12\" font-weight=\"600\" fill=\"#1c2733\" text-anchor=\"end\">${esc(r.label)}</text>`;\n    let x = padL;\n    r.segments.forEach(s => {\n      const bw = (w - padL - padR) * s.value / 100;\n      if (bw > 0.5){\n        g += `<rect x=\"${x.toFixed(1)}\" y=\"${y}\" width=\"${bw.toFixed(1)}\" height=\"30\" fill=\"${s.color}\"/>`;\n        if (bw > 34) g += `<text x=\"${(x+bw/2).toFixed(1)}\" y=\"${y+20}\" font-size=\"11\" fill=\"#fff\" text-anchor=\"middle\">${s.value}%</text>`;\n        x += bw;\n      }\n    });\n  });\n  return `<div class=\"chart-box\"><svg viewBox=\"0 0 ${w} ${h}\" width=\"${w}\">${g}</svg></div>`;\n}\n\n// Barra a soglie per l'incidenza rate/reddito\nfunction svgGauge(pct){\n  const w = 680, h = 74, padL = 14, padR = 14, bw = w - padL - padR;\n  const zones = [{to:20, c:'#2e9e5b'},{to:35, c:'#d99a06'},{to:60, c:'#d64545'}];\n  let g = '', x0 = padL, prev = 0;\n  zones.forEach(z => {\n    const zw = bw * (z.to - prev) / 60;\n    g += `<rect x=\"${x0}\" y=\"26\" width=\"${zw}\" height=\"16\" fill=\"${z.c}\" opacity=\".28\" rx=\"3\"/>`;\n    g += `<text x=\"${x0+zw}\" y=\"60\" font-size=\"10\" fill=\"#5a6b7d\" text-anchor=\"middle\">${z.to}%</text>`;\n    x0 += zw; prev = z.to;\n  });\n  const p = Math.min(60, Math.max(0, pct));\n  const xm = padL + bw * p / 60;\n  g += `<polygon points=\"${xm-7},14 ${xm+7},14 ${xm},26\" fill=\"#1c2733\"/>` +\n       `<text x=\"${xm}\" y=\"10\" font-size=\"12\" font-weight=\"700\" fill=\"#1c2733\" text-anchor=\"middle\">${fmtPct(pct,0)}</text>`;\n  return `<div class=\"chart-box\"><svg viewBox=\"0 0 ${w} ${h}\" width=\"${w}\">${g}</svg><div class=\"legend\"><span><i style=\"background:#2e9e5b\"></i>≤20% contenuta</span><span><i style=\"background:#d99a06\"></i>20–35% da monitorare</span><span><i style=\"background:#d64545\"></i>&gt;35% critica</span></div></div>`;\n}\n\n/* ============================================================\n   SIMULATORE DINAMICO GUIDATO\n   Parametri modificabili: accantonamento mensile, durata piano,\n   allocazione azionaria entro ±10 punti dal profilo coerente.\n   ============================================================ */\nlet MODEL = null;\nconst SIM = { monthly:0, years:10, tilt:0 };\n\nfunction simBaseEquity(){ return MODEL.allocs[MODEL.risk.profile].eq; }\n\nfunction updateSimulator(){\n  if (!MODEL) return;\n  SIM.monthly = +byId('simMonthly').value;\n  SIM.years = +byId('simYears').value;\n  SIM.tilt = +byId('simTilt').value;\n  byId('simMonthlyOut').textContent = fmtEUR(SIM.monthly) + '/mese';\n  byId('simYearsOut').textContent = SIM.years + ' anni (fine ' + (new Date().getFullYear() + SIM.years) + ')';\n  const eq = simBaseEquity() + SIM.tilt;\n  byId('simTiltOut').textContent = (SIM.tilt > 0 ? '+' : '') + SIM.tilt + ' p.ti → azionario ' + eq + '%';\n\n  // rendimento atteso: base del profilo ± 0,04 punti percentuali per ogni punto di azionario spostato\n  const r = RETURNS[MODEL.risk.profile] + SIM.tilt * 0.0004;\n  const base = runProjection(MODEL.investable, SIM.monthly, SIM.years, r);\n  const low  = runProjection(MODEL.investable, SIM.monthly, SIM.years, Math.max(0.005, r - SCENARIO_DELTA));\n  const high = runProjection(MODEL.investable, SIM.monthly, SIM.years, r + SCENARIO_DELTA);\n  const gap = base.final - MODEL.goal;\n  const growth = base.final - base.contributed;\n\n  const riskLabel = eq < 25 ? 'Basso' : (eq <= 45 ? 'Medio' : 'Alto');\n  const coherent = MODEL.risk.maxdd >= (eq < 25 ? 5 : (eq <= 45 ? 10 : 20));\n\n  const netF = base.contributed + growth * (1 - (MODEL.tax !== undefined ? MODEL.tax : 0.26));\n  byId('simKpis').innerHTML =\n    kpi(fmtEUR(base.final), 'Patrimonio finale stimato (scenario intermedio)') +\n    kpi(fmtEUR(low.final) + ' – ' + fmtEUR(high.final), 'Forchetta prudente – positivo') +\n    kpi(fmtEUR(base.contributed), 'Capitale versato (iniziale + accantonamenti)') +\n    kpi(fmtEUR(growth), 'Crescita stimata dai rendimenti') +\n    kpi(fmtEUR(netF), 'Valore netto stimato dopo fiscalità (se liquidato)') +\n    kpi((gap >= 0 ? '+' : '') + fmtEUR(gap), gap >= 0 ? 'Sopra l’obiettivo' : 'Sotto l’obiettivo di ' + fmtEUR(MODEL.goal)) +\n    kpi(riskLabel, 'Rischio qualitativo dell’allocazione simulata');\n\n  let msg = '';\n  if (!coherent) msg += `<div class=\"alert warn\">⚠️ Con azionario al ${eq}% le oscillazioni possibili superano la perdita massima che hai dichiarato di tollerare (~${MODEL.risk.maxdd}%). Meglio restare più vicino al profilo suggerito.</div>`;\n  if (gap < 0){\n    const plus100 = runProjection(MODEL.investable, SIM.monthly + 100, SIM.years, r).final - base.final;\n    const plus5y  = runProjection(MODEL.investable, SIM.monthly, SIM.years + 5, r).final - base.final;\n    msg += `<div class=\"alert info\">💡 Per avvicinarti all’obiettivo: <b>+100 €/mese</b> aggiungerebbero circa <b>${fmtEUR(plus100)}</b>; <b>+5 anni di orizzonte</b> circa <b>${fmtEUR(plus5y)}</b>. Piccole variazioni costanti contano più di scommesse sul rendimento.</div>`;\n  } else msg += '<div class=\"alert ok\">✅ Con queste ipotesi prudenti l’obiettivo appare raggiungibile. Ricorda: sono stime, non promesse.</div>';\n  byId('simMsg').innerHTML = msg;\n\n  byId('simChart').innerHTML = svgLines([\n    {name:'Prudente (' + fmtPct((r - SCENARIO_DELTA)*100,1) + ')', color:'#5a6b7d', points:low.points},\n    {name:'Intermedio (' + fmtPct(r*100,1) + ')', color:'#1f4e79', points:base.points},\n    {name:'Positivo (' + fmtPct((r + SCENARIO_DELTA)*100,1) + ')', color:'#0e8a6d', points:high.points}\n  ], {value:MODEL.goal, label:'Obiettivo ' + fmtEUR(MODEL.goal)}, 'anni da oggi');\n}\nfunction kpi(v, l){ return `<div class=\"kpi\"><div class=\"v\">${v}</div><div class=\"l\">${esc(l)}</div></div>`; }\n\n/* ============================================================\n   REPORT SEMPLIFICATO\n   ============================================================ */\nfunction generateSimpleReport(M){\n  const g = M.lights.filter(l => l.level === 'g'), y = M.lights.filter(l => l.level === 'y'), r = M.lights.filter(l => l.level === 'r');\n  const profLabel = {conservativo:'Prudente', bilanciato:'Bilanciato', dinamico:'Dinamico'}[M.risk.profile];\n  let h = '';\n\n  h += `<div class=\"simple-block\"><h4>📍 Dove sei oggi</h4>\n    <p>Il tuo patrimonio netto stimato è di circa <b>${fmtEUR(M.nw.netWorth)}</b>. Ogni anno la tua famiglia guadagna circa <b>${fmtEUR(M.cf.income)}</b>, spende circa <b>${fmtEUR(M.cf.expensesY)}</b> e riesce a mettere da parte circa <b>${fmtEUR(M.cf.savingsY)}</b>. La tua liquidità copre circa <b>${Math.round(M.ef.months)} mesi</b> di spese.</p></div>`;\n\n  h += `<div class=\"simple-block\"><h4>💪 Punti di forza</h4>` +\n    (g.length ? '<ul class=\"clean\">' + g.map(l => `<li><b>${esc(l.name)}</b>: ${esc(l.why)}</li>`).join('') + '</ul>' : '<p>Al momento non emergono aree pienamente solide: è normale all’inizio di un percorso. Si costruiscono un passo alla volta.</p>') + '</div>';\n\n  if (r.length + y.length){\n    h += `<div class=\"simple-block\" style=\"border-left-color:var(--warn)\"><h4>🔍 Aree fragili</h4><ul class=\"clean\">` +\n      r.map(l => `<li>🔴 <b>${esc(l.name)}</b>: ${esc(l.why)}</li>`).join('') +\n      y.map(l => `<li>🟡 <b>${esc(l.name)}</b>: ${esc(l.why)}</li>`).join('') + '</ul></div>';\n  }\n\n  // cosa controllare prima (ordine di priorità classico: emergenze → debiti cari → protezioni → investimenti)\n  const prio = [];\n  if (M.ef.months < 3) prio.push('Costruisci il fondo di emergenza: obiettivo 3–6 mesi di spese (' + fmtEUR(M.ef.target) + ') su un conto separato e subito disponibile.');\n  if (M.debt.hasRevolving) prio.push('Estingui le carte revolving: costano più di quanto qualsiasi investimento prudente possa rendere.');\n  if (M.debt.rateOnIncome > 0.35) prio.push('Riduci il peso delle rate: sopra il 35% del reddito ogni imprevisto diventa pericoloso.');\n  if (M.ins.red > 0) prio.push('Colma le protezioni essenziali mancanti (vedi sezione assicurativa): proteggere i rischi gravi viene prima di investire.');\n  if (M.cf.savingsRate < 0.05 && M.cf.implicitSavings > 0) prio.push('Alza il tasso di risparmio: anche 50–100 € in più al mese cambiano il piano nel lungo periodo.');\n  if (!prio.length) prio.push('Le basi appaiono in ordine: puoi concentrarti su costanza degli accantonamenti e revisione annuale del piano.');\n  h += `<div class=\"simple-block\"><h4>✅ Cosa controllare prima</h4><ul class=\"clean\">` + prio.map(p => '<li>' + esc(p) + '</li>').join('') + '</ul></div>';\n\n  h += `<div class=\"simple-block\"><h4>⚖️ Il piano è sostenibile?</h4>\n    <p>${M.sustainable ? 'Sì: il risparmio che hai indicato è compatibile con il tuo bilancio.' : 'Attenzione: il risparmio indicato sembra superiore a quanto il bilancio (reddito meno spese) consente davvero. Rivedi le stime prima di fissare il piano.'}\n    ${M.cf.implicitSavings < 0 ? ' Le spese superano il reddito: prima di ogni piano di investimento serve riportare il bilancio in positivo.' : ''}</p>\n    <p>Impegni finanziari: ${M.nw.totalDebt === 0 ? 'non hai debiti — ottimo punto di partenza.' : 'le rate assorbono circa <b>' + fmtPct(M.debt.rateOnIncome*100,0) + '</b> del reddito' + (M.debt.rateOnIncome <= 0.2 ? ', un livello gestibile.' : (M.debt.rateOnIncome <= 0.35 ? ', un livello da tenere d’occhio.' : ', un livello critico da ridurre.'))}</p>\n    <p>Coperture assicurative: ${M.ins.red > 0 ? 'ci sono <b>lacune importanti</b> da valutare al più presto.' : (M.ins.yellow >= 3 ? 'diverse aree sono da completare, ma senza urgenze drammatiche.' : 'l’impianto di protezione appare ragionevole per il tuo profilo.')}</p></div>`;\n\n  h += `<div class=\"simple-block\"><h4>🧭 Profilo suggerito: <b>${profLabel}</b></h4>\n    <p>In base a età, orizzonte, esperienza e tolleranza alle perdite, l’allocazione più coerente per te è quella <b>${profLabel.toLowerCase()}</b> (la trovi evidenziata più sotto). Con ipotesi prudenti, continuando a risparmiare ${fmtEUR(M.monthly)}/mese per ${M.years} anni, il tuo capitale potrebbe passare da ${fmtEUR(M.investable)} a circa <b>${fmtEUR(M.projBase.final)}</b> (tra ${fmtEUR(M.projLow.final)} e ${fmtEUR(M.projHigh.final)} negli scenari prudente e positivo). ${M.goalGap <= 0 ? 'L’obiettivo di ' + fmtEUR(M.goal) + ' appare raggiungibile.' : 'Rispetto all’obiettivo di ' + fmtEUR(M.goal) + ' mancherebbero circa ' + fmtEUR(M.goalGap) + ': usa il simulatore per capire cosa cambia con più risparmio o più tempo.'}</p>\n    <p class=\"small muted\">Come è stato fissato l’obiettivo di ${fmtEUR(M.goal)}: ${esc(M.goalLabel)}.</p></div>`;\n\n  if (M.couple){\n    h += `<div class=\"simple-block\"><h4>👫 Analisi di coppia</h4>\n    <p>Del reddito familiare di ${fmtEUR(M.cf.income)}, tu ne porti circa il <b>${fmtPct(M.couple.share*100,0)}</b> (${fmtEUR(M.couple.mine)}) e il tuo partner ${fmtEUR(M.couple.theirs)}. ${M.couple.concentration\n      ? 'Il reddito dipende in gran parte da <b>' + (M.couple.keyPerson === 'tu' ? 'te' : 'una sola persona (il tuo partner)') + '</b>: proteggere chi lo produce (vita caso morte, invalidità) è la priorità assicurativa numero uno della famiglia.'\n      : 'Il reddito è ben distribuito tra voi due: la famiglia è più resiliente se uno dei due deve fermarsi.'}</p>\n    ${M.couple.resp.length\n      ? '<p>⚠️ Il tuo partner ricopre ruoli con possibile esposizione patrimoniale (' + esc(M.couple.respLabels.join(', ')) + '): in certe condizioni (ad es. comunione dei beni) anche il patrimonio familiare può esserne coinvolto. Da verificare con un professionista: coperture di responsabilità del partner e regime patrimoniale.</p>'\n      : '<p>Nessun ruolo a rischio patrimoniale segnalato per il partner.</p>'}</div>`;\n  }\n\n  h += `<div class=\"simple-block\"><h4>🧾 Fisco in breve</h4>\n    <p>In Italia i guadagni degli investimenti sono in genere tassati al <b>26%</b> (12,5% per i titoli di Stato) e sul conto titoli si paga un’imposta di bollo dello <b>0,2% l’anno</b>. Se a fine piano liquidassi tutto, il patrimonio stimato di ${fmtEUR(M.projBase.final)} varrebbe circa <b>${fmtEUR(M.netFinal)}</b> netti (stima). La previdenza integrativa gode di vantaggi fiscali: deduzione dei versamenti fino a ~5.164 €/anno e tassazione finale agevolata (15%, riducibile fino al 9%).</p></div>`;\n\n  if (M.risk.warnings.length)\n    h += `<div class=\"alert warn\">⚠️ <div>${M.risk.warnings.map(esc).join('<br>')}</div></div>`;\n\n  return h;\n}\n\n/* ============================================================\n   REPORT AVANZATO\n   ============================================================ */\nfunction generateAdvancedReport(M){\n  const t = (rows, headers) => '<table class=\"t\"><tr>' + headers.map(x => '<th>' + x + '</th>').join('') + '</tr>' +\n    rows.map(r => '<tr' + (r.tot ? ' class=\"trow-tot\"' : '') + '><td>' + r.k + '</td><td class=\"num\">' + r.v + '</td>' + (r.n !== undefined ? '<td class=\"small muted\">' + r.n + '</td>' : '') + '</tr>').join('') + '</table>';\n\n  let h = '<div class=\"chart-title\">Tabella patrimonio</div>' + t([\n    {k:'Liquidità', v:fmtEUR(M.nw.liq)},{k:'Investimenti finanziari', v:fmtEUR(M.nw.inv)},\n    {k:'Immobili', v:fmtEUR(M.nw.imm)},{k:'Previdenza integrativa', v:fmtEUR(M.nw.prev)},\n    {k:'Altri asset', v:fmtEUR(M.nw.altri)},{k:'Patrimonio lordo', v:fmtEUR(M.nw.grossAssets), tot:true},\n    {k:'Debiti totali', v:'− ' + fmtEUR(M.nw.totalDebt)},{k:'Patrimonio netto', v:fmtEUR(M.nw.netWorth), tot:true}\n  ], ['Voce','Valore stimato']);\n\n  h += '<div class=\"chart-title\">Composizione del patrimonio lordo</div><div class=\"chart-box\" style=\"text-align:center\">' +\n    svgDonut([\n      {label:'Liquidità', value:M.nw.liq, color:PALETTE[1]},\n      {label:'Investimenti', value:M.nw.inv, color:PALETTE[0]},\n      {label:'Immobili', value:M.nw.imm, color:PALETTE[3]},\n      {label:'Previdenza', value:M.nw.prev, color:PALETTE[2]},\n      {label:'Altri asset', value:M.nw.altri, color:PALETTE[4]}\n    ]) + '</div>';\n\n  h += '<div class=\"chart-title\">Tabella cash flow</div>' + t([\n    {k:'Reddito annuo netto', v:fmtEUR(M.cf.income)},\n    {k:'Spese annue stimate', v:'− ' + fmtEUR(M.cf.expensesY)},\n    {k:'Saldo implicito', v:fmtEUR(M.cf.implicitSavings)},\n    {k:'Risparmio annuo dichiarato', v:fmtEUR(M.cf.savingsY), tot:true},\n    {k:'Tasso di risparmio', v:fmtPct(M.cf.savingsRate*100,1)}\n  ], ['Voce','Valore']);\n  if (M.cf.incoherent) h += '<div class=\"alert warn\">⚠️ Reddito, spese e risparmio dichiarati non tornano perfettamente tra loro: i range possono spiegare parte dello scarto, ma conviene ricontrollare le stime.</div>';\n\n  h += '<div class=\"chart-title\">Tabella debiti</div>';\n  if (M.nw.totalDebt === 0 && M.debt.rateY === 0) h += '<p class=\"muted small\">Nessun debito dichiarato.</p>';\n  else {\n    h += t([\n      {k:'Mutuo residuo', v:fmtEUR(M.nw.mutuo)},\n      {k:'Altri debiti (' + ((A.tipiDebiti||[]).filter(x=>x!=='nessuno').map(v=>(optOf('tipiDebiti',v)||{l:v}).l).join(', ') || '—') + ')', v:fmtEUR(M.nw.altriDeb)},\n      {k:'Totale debiti', v:fmtEUR(M.nw.totalDebt), tot:true},\n      {k:'Rata annua totale', v:fmtEUR(M.debt.rateY)},\n      {k:'Incidenza rate / reddito', v:fmtPct(M.debt.rateOnIncome*100,1)},\n      {k:'Debiti / reddito annuo', v:(M.debt.debtToIncome).toFixed(1).replace('.',',') + '×'},\n      {k:'Durata residua massima', v:labelOf('durataImpegni')}\n    ], ['Voce','Valore']);\n    if (M.nw.debtEstimated) h += '<div class=\"alert info\">ℹ️ Percorso Light: il debito residuo è <b>stimato dalla rata mensile</b> (ipotesi: durata media residua 5 anni). Per il dato puntuale rifai l’analisi in modalità Standard o Approfondita.</div>';\n    h += '<div class=\"chart-title\">Composizione debiti</div><div class=\"chart-box\" style=\"text-align:center\">' +\n      svgDonut([{label:'Mutuo', value:M.nw.mutuo, color:PALETTE[0]},{label:'Altri debiti', value:M.nw.altriDeb, color:PALETTE[5]}], 190) + '</div>';\n  }\n  h += '<div class=\"chart-title\">Incidenza rate sul reddito</div>' + svgGauge(M.debt.rateOnIncome*100);\n\n  // Indicatori di sostenibilità\n  h += '<div class=\"chart-title\">Indicatori di sostenibilità</div><div class=\"kpis\">' +\n    kpi(fmtPct(M.cf.savingsRate*100,0), 'Tasso di risparmio (rif. ≥15%)') +\n    kpi(Math.round(M.ef.months) + ' mesi', 'Fondo emergenza (rif. ≥6 mesi)') +\n    kpi(fmtPct(M.debt.rateOnIncome*100,0), 'Rate/reddito (rif. ≤20%)') +\n    kpi((M.debt.debtToIncome).toFixed(1).replace('.',',') + '×', 'Debiti/reddito annuo') +\n    kpi(fmtEUR(M.investable), 'Capitale investibile (oltre 6 mesi di riserva)') +\n    kpi(fmtEUR(M.goal), 'Capitale obiettivo a fine piano') + '</div>';\n\n  // Coperture assicurative\n  h += '<div class=\"chart-title\">Coperture assicurative e gap</div>' + t(\n    M.ins.gaps.map(g => ({k:g.area, v:'<span class=\"pill ' + g.level + '\">' + (g.level==='g'?'OK':(g.level==='y'?'Da valutare':'Critico')) + '</span>', n:g.why})),\n    ['Area','Stato','Nota']);\n  h += svgHBars(M.ins.gaps.map(g => ({\n    label:g.area, value:g.level==='g'?100:(g.level==='y'?55:20),\n    color:g.level==='g'?'#2e9e5b':(g.level==='y'?'#d99a06':'#d64545'),\n    text:g.level==='g'?'adeguata':(g.level==='y'?'da valutare':'lacuna critica')})), 100);\n\n  // Simulazione patrimoniale (scenari base)\n  h += '<div class=\"chart-title\">Simulazione patrimoniale — profilo ' + esc(M.risk.profile) + ' (' + fmtPct(M.baseR*100,1) + ' atteso)</div>';\n  h += svgLines([\n    {name:'Prudente ' + fmtPct((Math.max(0.005, M.baseR-SCENARIO_DELTA))*100,1), color:'#5a6b7d', points:M.projLow.points},\n    {name:'Intermedio ' + fmtPct(M.baseR*100,1), color:'#1f4e79', points:M.projBase.points},\n    {name:'Positivo ' + fmtPct((M.baseR+SCENARIO_DELTA)*100,1), color:'#0e8a6d', points:M.projHigh.points}\n  ], {value:M.goal, label:'Obiettivo'}, 'anni (piano di ' + M.years + ' anni, ' + fmtEUR(M.monthly) + '/mese)');\n  h += t([\n    {k:'Capitale iniziale investibile', v:fmtEUR(M.investable)},\n    {k:'Versamenti totali nel piano', v:fmtEUR(M.projBase.contributed - M.investable)},\n    {k:'Scenario prudente', v:fmtEUR(M.projLow.final)},\n    {k:'Scenario intermedio', v:fmtEUR(M.projBase.final), tot:true},\n    {k:'Scenario positivo', v:fmtEUR(M.projHigh.final)},\n    {k:'Gap vs obiettivo (scenario intermedio)', v:(M.goalGap>0?'− ':'+ ') + fmtEUR(Math.abs(M.goalGap))}\n  ], ['Scenario','Valore a fine piano']);\n\n  // Analisi di coppia\n  if (M.couple){\n    h += '<div class=\"chart-title\">Analisi di coppia</div>' + t([\n      {k:'Reddito familiare annuo netto', v:fmtEUR(M.cf.income)},\n      {k:'Apporto tuo (' + fmtPct(M.couple.share*100,0) + ')', v:fmtEUR(M.couple.mine)},\n      {k:'Apporto del partner (' + fmtPct((1-M.couple.share)*100,0) + ')', v:fmtEUR(M.couple.theirs)},\n      {k:'Concentrazione del reddito', v:M.couple.concentration ? '⚠️ Alta' : 'Equilibrata', n:M.couple.concentration ? 'la famiglia dipende soprattutto da ' + (M.couple.keyPerson === 'tu' ? 'te' : 'il partner') + ': priorità a TCM e copertura invalidità su quella persona' : 'buona resilienza del bilancio familiare'},\n      {k:'Ruoli a rischio patrimoniale del partner', v:M.couple.resp.length ? '⚠️ Presenti' : 'Nessuno', n:M.couple.resp.length ? esc(M.couple.respLabels.join(', ')) + ' — verificare RC professionale del partner e regime patrimoniale (comunione/separazione dei beni)' : ''}\n    ], ['Voce','Valore','Nota']);\n  }\n\n  // Decumulo e fiscalità\n  h += '<div class=\"chart-title\">Decumulo e fiscalità (stime semplificate)</div>';\n  if (M.deep && isFI() && isAnswered(Q('speseTarget'))){\n    const needM = Math.max(0, midVal('speseTarget') - midVal('altreEntrateFuture'));\n    h += t([\n      {k:'Tenore di vita mensile desiderato', v:fmtEUR(midVal('speseTarget'))},\n      {k:'Altre entrate previste (pensione, affitti…)', v:'− ' + fmtEUR(midVal('altreEntrateFuture'))},\n      {k:'Fabbisogno mensile da capitale', v:fmtEUR(needM), tot:true},\n      {k:'Fabbisogno annuo netto', v:fmtEUR(needM*12)},\n      {k:'Capitale obiettivo (25× + fiscalità stimata)', v:fmtEUR(M.goal), tot:true},\n      {k:'Età di inizio decumulo indicata', v:labelOf('etaObiettivo')},\n      {k:'Anni di accumulo residui stimati', v:M.years + ' anni'}\n    ], ['Voce','Valore']);\n    h += '<div class=\"alert info\">💡 <div>Con la <b>regola del 4%</b> un prelievo annuo pari al 4% del capitale iniziale è storicamente risultato sostenibile su orizzonti lunghi, ma non è garantito. La correzione fiscale ipotizza che circa metà di ogni prelievo sia rendimento tassato all’aliquota stimata (' + fmtPct(M.tax*100,1) + ').</div></div>';\n  }\n  h += t([\n    {k:'Aliquota stimata sui guadagni', v:fmtPct(M.tax*100,1), n:A.tipoStrumenti ? 'in base agli strumenti indicati (26% standard, 12,5% titoli di Stato, 20% proxy misto)' : 'ipotesi standard 26% (non specificato)'},\n    {k:'Guadagni stimati a fine piano (scenario intermedio)', v:fmtEUR(M.growth)},\n    {k:'Imposta stimata in caso di liquidazione totale', v:'− ' + fmtEUR(Math.round(M.growth * M.tax))},\n    {k:'Valore netto stimato dopo fiscalità', v:fmtEUR(M.netFinal), tot:true},\n    {k:'Bollo titoli cumulato stimato (0,2%/anno)', v:'~ ' + fmtEUR(M.bolloStima), n:'già un motivo per preferire strumenti e depositi efficienti'}\n  ], ['Voce','Valore']);\n  h += '<p class=\"small muted\">Nota previdenza integrativa: versamenti deducibili fino a 5.164,57 €/anno (risparmio IRPEF immediato), tassazione finale agevolata dal 15% al 9% in base agli anni di partecipazione. Il TFR in fondo pensione gode dello stesso regime. Approfondisci con un consulente previdenziale.</p>';\n\n  // Assunzioni\n  h += `<div class=\"chart-title\">Assunzioni utilizzate</div><ul class=\"clean small muted\">\n    <li>Rendimenti annui nominali attesi (lordi): conservativo 2,0% · bilanciato 3,2% · dinamico 4,5%; scenari prudente/positivo a ±1,5 punti.</li>\n    <li>Capitalizzazione mensile dei versamenti; versamenti costanti; nessuna interruzione.</li>\n    <li>Gli importi a range usano il valore centrale della fascia (o il valore preciso se inserito).</li>\n    <li>Fiscalità: 26% sui guadagni (12,5% titoli di Stato, 20% proxy per portafogli misti), applicata come stima alla liquidazione; bollo 0,2% annuo sul saldo medio. Non sono modellati: minusvalenze compensabili, zainetto fiscale, regime gestito vs amministrato.</li>\n    <li>Percorso essenziale: debiti residui stimati dalla rata (durata media ipotizzata 5 anni); obiettivo di capitale da default prudenti dichiarati.</li>\n    <li>Inflazione e costi di prodotto non modellati esplicitamente: i rendimenti prudenti li compensano solo in parte.</li>\n    <li>Capitale investibile = investimenti attuali + liquidità eccedente 6 mesi di spese.</li>\n    <li>Soglie: fondo emergenza ≥6 mesi; rate/reddito ≤20% (critico &gt;35%); tasso di risparmio ≥15%.</li>\n  </ul>`;\n  return h;\n}\n\n/* ============================================================\n   TIPS & TRICKS / PRINCIPI GUIDA\n   ============================================================ */\nfunction generateTipsAndTricks(){\n  const tips = [\n    {t:'Il comportamento batte l’analisi', p:'Il risultato finanziario dipende più dalla disciplina (risparmiare con costanza, non vendere nel panico) che dall’intelligenza dei singoli investimenti. Proteggiti dalle tue reazioni prima che dal mercato.', s:'Morgan Housel, “La psicologia dei soldi”'},\n    {t:'Diffida dell’istinto sui soldi', p:'Le decisioni rapide e intuitive sono piene di errori sistematici (ancoraggio, eccesso di fiducia). Sulle scelte patrimoniali importanti rallenta: dormici sopra e usa regole scritte in anticipo.', s:'Daniel Kahneman, “Pensieri lenti e veloci”'},\n    {t:'Le perdite pesano il doppio', p:'Una perdita fa male circa il doppio di quanto un guadagno uguale faccia piacere. Per questo si vende ai minimi. Scegli un’allocazione le cui oscillazioni puoi sopportare davvero, non quella con il rendimento più alto.', s:'Kahneman e Tversky, “Prospect Theory”'},\n    {t:'Ricchezza è ciò che non vedi', p:'I patrimoni solidi si costruiscono spendendo meno di quanto si guadagna per decenni, non con lo stile di vita visibile. Il tasso di risparmio è la variabile che controlli di più.', s:'Stanley e Danko, “Il milionario della porta accanto”'},\n    {t:'Paga prima te stesso', p:'Accantona una quota fissa del reddito appena arriva (idealmente ≥10%), automaticamente, prima di ogni altra spesa. Ciò che resta si spende comunque.', s:'George S. Clason, “L’uomo più ricco di Babilonia”'},\n    {t:'I costi sono certi, i rendimenti no', p:'Ogni punto percentuale di costo annuo è rendimento perso per sempre. Strumenti semplici, diversificati e a basso costo battono nel tempo la maggior parte delle alternative care.', s:'John C. Bogle, “Il piccolo libro dell’investimento vincente”'},\n    {t:'Il passato non si ripete su comando', p:'I rendimenti storici non garantiscono quelli futuri e battere sistematicamente il mercato è raro. Non scegliere un fondo solo perché “ha reso bene ultimamente”.', s:'Burton G. Malkiel, “A Random Walk Down Wall Street”; Eugene Fama, EMH'},\n    {t:'Quattro pilastri, non uno', p:'Teoria, storia, psicologia e industria del risparmio: trascurarne uno costa caro. In particolare, studia le crisi passate: chi conosce il 1929 o il 2008 si spaventa meno nei ribassi.', s:'William J. Bernstein, “I quattro pilastri dell’investimento”'},\n    {t:'Diversifica: è l’unico pasto gratis', p:'Combinare asset che non si muovono insieme riduce il rischio senza sacrificare proporzionalmente il rendimento. Nessun singolo titolo o Paese merita una fetta dominante del patrimonio.', s:'Harry Markowitz, “Portfolio Selection”'},\n    {t:'Preparati a ciò che non è mai successo', p:'Gli eventi estremi e imprevisti dominano la storia finanziaria. Margini di sicurezza (liquidità, assicurazioni, poco debito) valgono più di previsioni precise ma fragili.', s:'Nassim N. Taleb, “Il Cigno Nero”'},\n    {t:'Non confondere cicli e permanenza', p:'Debito, tassi e inflazione si muovono in grandi cicli: ciò che ha funzionato negli ultimi 10 anni può non funzionare nei prossimi 10. Costruisci un portafoglio che regga più scenari.', s:'Ray Dalio, “Principles”; “The Changing World Order”'},\n    {t:'L’euforia è un segnale, non un invito', p:'Quando “tutti guadagnano facilmente” (1929, dot-com, 2008) il rischio è massimo proprio mentre sembra minimo. Distingui il rischio percepito dal rischio reale.', s:'Robert Shiller, “Irrational Exuberance”; Galbraith, “The Great Crash, 1929”'},\n    {t:'Prima i rischi catastrofali', p:'Assicura ciò che non puoi permetterti di perdere (morte, invalidità, responsabilità civile) prima di ottimizzare i rendimenti. Un gap di protezione può azzerare decenni di risparmio.', s:'Principio cardine della pianificazione; cfr. Bernstein, “I quattro pilastri”'},\n    {t:'Il tempo nel mercato batte il timing', p:'Su orizzonti lunghi l’azionario diversificato ha storicamente premiato la pazienza, ma solo chi è rimasto investito. Allunga l’orizzonte invece di cercare il momento perfetto.', s:'Jeremy Siegel, “Stocks for the Long Run”'},\n    {t:'Razionalità limitata: semplifica', p:'Nessuno può elaborare tutte le informazioni: decisioni “abbastanza buone”, semplici e ripetibili battono strategie perfette ma ingestibili. Automatizza risparmio e ribilanciamento.', s:'Herbert Simon, “Administrative Behavior”'}\n  ];\n  return tips.map(x => `<div class=\"tip\"><b>${esc(x.t)}</b><p>${esc(x.p)}</p><div class=\"src\">Per approfondire: ${esc(x.s)}</div></div>`).join('');\n}\n\n/* ============================================================\n   RENDERING RISULTATI\n   ============================================================ */\nfunction renderTrafficLights(lights){\n  return '<div class=\"lights-grid\">' + lights.map(l =>\n    `<div class=\"light-card\"><span class=\"light ${l.level}\" style=\"margin-top:3px\"></span><div><b>${esc(l.name)}</b> <span class=\"pill ${l.level}\">${l.level==='g'?'Adeguata':(l.level==='y'?'Da monitorare':'Critica')}</span><p>${esc(l.why)}</p></div></div>`\n  ).join('') + '</div>';\n}\n\nfunction renderAllocations(M){\n  const names = {conservativo:'🛡️ Bassa propensione (Prudente)', bilanciato:'⚖️ Profilo intermedio (Bilanciato)', dinamico:'🚀 Alta propensione (Dinamico)'};\n  const rows = ['conservativo','bilanciato','dinamico'];\n  let h = '<div class=\"alloc-grid\">';\n  rows.forEach(p => {\n    const a = M.allocs[p], sug = p === M.risk.profile;\n    h += `<div class=\"alloc-card${sug ? ' suggested' : ''}\">` +\n      (sug ? '<div class=\"tag\">✔ coerente con il tuo profilo</div>' : '') +\n      `<h4>${names[p]}</h4><p class=\"small muted\">Rendimento atteso ~${fmtPct(RETURNS[p]*100,1)}/anno</p>` +\n      `<div class=\"alloc-row\"><span>Liquidità / fondo emergenza</span><b>${a.liq}%</b></div>` +\n      `<div class=\"alloc-row\"><span>Obbligazionario</span><b>${a.bond}%</b></div>` +\n      `<div class=\"alloc-row\"><span>Azionario globale</span><b>${a.eq}%</b></div>` +\n      `<div class=\"alloc-row\"><span>Oro / real asset</span><b>${a.gold}%</b></div>` +\n      `<div class=\"alloc-row\"><span>Previdenza / fondo pensione</span><b>${a.pens}%</b></div></div>`;\n  });\n  h += '</div>';\n  h += '<div class=\"chart-title\">Confronto visivo</div>' + svgStacked(rows.map(p => ({label:p.charAt(0).toUpperCase()+p.slice(1), segments:[\n    {value:M.allocs[p].liq, color:PALETTE[1]},{value:M.allocs[p].bond, color:PALETTE[2]},\n    {value:M.allocs[p].eq, color:PALETTE[0]},{value:M.allocs[p].gold, color:PALETTE[3]},\n    {value:M.allocs[p].pens, color:PALETTE[4]}]})));\n  h += '<div class=\"legend\"><span><i style=\"background:'+PALETTE[1]+'\"></i>Liquidità</span><span><i style=\"background:'+PALETTE[2]+'\"></i>Obbligazioni</span><span><i style=\"background:'+PALETTE[0]+'\"></i>Azionario</span><span><i style=\"background:'+PALETTE[3]+'\"></i>Oro/real asset</span><span><i style=\"background:'+PALETTE[4]+'\"></i>Previdenza</span></div>';\n  h += '<div class=\"alert info\">🛡️ <div>Percentuali <b>indicative e prudenti</b>, da adattare con un consulente. La <b>protezione assicurativa dei rischi gravi va finanziata prima o insieme</b> agli investimenti: nessuna allocazione regge se un imprevisto non coperto azzera il capitale.' +\n    (M.ef.months < 6 ? ' Nel tuo caso, completa prima il fondo di emergenza (mancano circa ' + fmtEUR(M.ef.gap) + ').' : '') + '</div></div>';\n  return h;\n}\n\nfunction showResults(){\n  MODEL = computeAll();\n  const M = MODEL;\n  byId('wizard').hidden = true;\n  byId('results').hidden = false;\n\n  const profLabel = {conservativo:'Prudente', bilanciato:'Bilanciato', dinamico:'Dinamico'}[M.risk.profile];\n  const healthScore = computeHealthScore(M.lights);\n\n  // bonus di completamento (una tantum) e festeggiamento\n  award('report', 50, 'analisi completata!');\n  if (M.tier === 3) award('deep', 50, 'percorso Approfondito: trofeo Analista');\n  if (M.couple) award('couple', 20, 'analisi di coppia');\n  confettiBurst();\n\n  let h = '';\n\n  // KPI di sintesi\n  h += `<div class=\"card\"><h2>📊 La tua fotografia</h2><div class=\"kpis\">` +\n    kpi(healthScore + '/100', 'Indice di salute finanziaria') +\n    kpi(fmtEUR(M.nw.netWorth), 'Patrimonio netto stimato') +\n    kpi(fmtEUR(M.cf.income), 'Reddito annuo netto') +\n    kpi(fmtEUR(M.cf.savingsY), 'Risparmio annuo (' + fmtPct(M.cf.savingsRate*100,0) + ')') +\n    kpi(Math.round(M.ef.months) + ' mesi', 'Copertura fondo emergenza') +\n    kpi(fmtPct(M.debt.rateOnIncome*100,0), 'Rate / reddito') +\n    kpi(profLabel, 'Profilo di rischio coerente') +\n    kpi(M.tierLabel, 'Percorso di analisi svolto') + '</div>' +\n    (M.tier === 1 ? '<div class=\"alert warn\">⚠️ <b>Percorso Light:</b> questa analisi è più imprecisa, perché basata su poche domande e su stime standard (debiti, patrimonio di dettaglio, profilo di rischio). Per un quadro affidabile rifai l’analisi con il percorso <b>Approfondito</b>.</div>' : '') +\n    (M.cf.incoherent ? '<div class=\"alert warn\">⚠️ Le stime di reddito, spese e risparmio non sono perfettamente coerenti tra loro: i risultati vanno letti come ordine di grandezza.</div>' : '') + '</div>';\n\n  // Semafori\n  h += `<div class=\"card\" id=\"secLights\"><h2>🚦 Valutazione a semaforo</h2><p class=\"muted small\">Verde = tendenzialmente adeguata · Giallo = da monitorare o migliorare · Rosso = potenzialmente critica.</p>` + renderTrafficLights(M.lights) + '</div>';\n\n  // Gamification: trofei e missioni (solo se la modalità gioco è attiva)\n  if (GAME.enabled){\n    h += `<div class=\"card\" id=\"secBadges\"><h2>🏆 I tuoi trofei</h2>` + renderBadges(M) +\n      `<p class=\"small muted\" style=\"margin-top:12px\">Punti totali: <b>${GAME.xp}</b> · Livello: <b>${esc(gameLevel().cur.name)}</b></p></div>`;\n    h += `<div class=\"card\" id=\"secMissions\"><h2>🎯 Le tue prossime missioni</h2><p class=\"muted small\">Sfide concrete generate dalle tue aree più deboli: ogni missione completata nella vita reale migliora l’analisi (e il punteggio) della prossima volta.</p>` + renderMissions(M, healthScore) + '</div>';\n  }\n\n  // Report semplificato\n  h += `<div class=\"card\" id=\"secSimple\"><h2>📄 Report semplificato</h2>` + generateSimpleReport(M) + '</div>';\n\n  // Simulatore\n  const maxMonthly = Math.max(500, Math.min(3000, Math.ceil((M.cf.savingsM * 2 + 200) / 50) * 50));\n  h += `<div class=\"card\" id=\"secSim\"><h2>🎛️ Simulatore guidato</h2>\n    <p class=\"muted small\">Un simulatore volutamente limitato: puoi variare solo accantonamento, durata e (di poco) l’allocazione. Rendimenti prudenti e dichiarati — le curve sono stime, non previsioni.</p>\n    <div class=\"sim-controls\" id=\"simControls\">\n      <div class=\"sim-ctl\"><label>Accantonamento mensile <output id=\"simMonthlyOut\"></output></label>\n        <input type=\"range\" id=\"simMonthly\" min=\"0\" max=\"${maxMonthly}\" step=\"50\" value=\"${Math.min(maxMonthly, M.cf.savingsM)}\">\n        <div class=\"sim-note\">Il tuo risparmio attuale è ~${fmtEUR(M.cf.savingsM)}/mese</div></div>\n      <div class=\"sim-ctl\"><label>Durata del piano <output id=\"simYearsOut\"></output></label>\n        <input type=\"range\" id=\"simYears\" min=\"5\" max=\"40\" step=\"1\" value=\"${Math.min(40, Math.max(5, M.years))}\">\n        <div class=\"sim-note\">Orizzonte dichiarato: ~${M.years} anni</div></div>\n      <div class=\"sim-ctl\"><label>Allocazione azionaria <output id=\"simTiltOut\"></output></label>\n        <input type=\"range\" id=\"simTilt\" min=\"-10\" max=\"10\" step=\"5\" value=\"0\">\n        <div class=\"sim-note\">Max ±10 punti rispetto al profilo ${profLabel} (azionario base ${M.allocs[M.risk.profile].eq}%)</div></div>\n    </div>\n    <div class=\"kpis\" id=\"simKpis\"></div>\n    <div id=\"simMsg\"></div>\n    <div id=\"simChart\"></div></div>`;\n\n  // Allocazioni\n  h += `<div class=\"card\" id=\"secAlloc\"><h2>🥧 Tre allocazioni indicative</h2>` + renderAllocations(M) + '</div>';\n\n  // Report avanzato\n  h += `<div class=\"card\" id=\"secAdv\"><h2>📈 Report avanzato</h2>` + generateAdvancedReport(M) + '</div>';\n\n  // Tips\n  h += `<div class=\"card\" id=\"secTips\"><h2>💡 Tips &amp; Tricks — Principi guida</h2><p class=\"muted small\">Sintesi operative ispirate alla letteratura finanziaria: ogni scheda indica la fonte per approfondire.</p>` + generateTipsAndTricks() + '</div>';\n\n  // Limiti e prossimi passi\n  h += `<div class=\"card\" id=\"secLimits\"><h2>🧭 Limiti di questa analisi e prossimi passi</h2>\n    <h3>Cosa questo strumento NON fa</h3>\n    <ul class=\"clean small\">\n      <li>Non è consulenza finanziaria, assicurativa, fiscale o legale personalizzata.</li>\n      <li>Usa valori centrali dei range e ipotesi semplificate: non conosce contratti, tasse, costi reali dei tuoi prodotti.</li>\n      <li>Non modella inflazione puntuale, sequenza dei rendimenti, eventi di vita (separazioni, eredità, spese sanitarie straordinarie).</li>\n      <li>Non analizza coperture professionali o aziendali: per le responsabilità qualificate serve una verifica dedicata.</li>\n      <li>Le simulazioni non sono previsioni: i mercati possono fare molto peggio (e meglio) degli scenari mostrati.</li>\n    </ul>\n    <h3>Prossimi passi suggeriti</h3>\n    <ul class=\"clean small\">\n      <li>Stampa o salva in PDF questo report e portalo a un <b>consulente finanziario abilitato</b> e a un <b>intermediario assicurativo</b>: sarà una base di discussione già strutturata.</li>\n      <li>Rifai l’analisi 1–2 volte l’anno o dopo eventi importanti (figli, casa, cambio lavoro).</li>\n      <li>Verifica per prime le aree rosse del semaforo, poi le gialle.</li>\n    </ul>\n    <p class=\"muted small\" style=\"margin-top:10px\">🔒 Promemoria privacy: i dati restano su questo dispositivo finché non vengono inviati all'agenzia; dopo l'invio vengono cancellati.</p></div>`;\n\n  byId('resultsBody').innerHTML = h;\n  updateSimulator();\n  window.scrollTo(0, 0);\n}\n\n/* ============================================================\n   EVENT DELEGATION (compatibilità iOS/Safari e visualizzatori\n   che bloccano i gestori inline onclick/onchange)\n   ============================================================ */\ndocument.addEventListener('click', function(e){\n  const t = e.target.closest ? e.target.closest('[data-action],[data-goto]') : null;\n  if (!t) return;\n  if (t.hasAttribute('data-goto')){ gotoStep(+t.getAttribute('data-goto')); return; }\n  const a = t.getAttribute('data-action');\n  if (a === 'start') startWizard();\n  else if (a === 'prev') prevStep();\n  else if (a === 'next') nextStep();\n  else if (a === 'print') window.print();\n  else if (a === 'restart') restart();\n});\ndocument.addEventListener('change', function(e){\n  const el = e.target;\n  if (el.id === 'gameToggle'){ GAME.enabled = el.checked; updateXPBar(); return; } // partecipazione volontaria\n  if (el.tagName === 'SELECT' && el.hasAttribute('data-q')) setAnswer(el.getAttribute('data-q'), el.value);\n  else if (el.type === 'radio' && el.hasAttribute('data-q')) setAnswer(el.getAttribute('data-q'), el.value);\n  else if (el.type === 'checkbox' && el.hasAttribute('data-q')) toggleMulti(el.getAttribute('data-q'), el.getAttribute('data-v'), el.checked);\n  else if (el.hasAttribute('data-precise')) setPrecise(el.getAttribute('data-precise'), el.value);\n});\ndocument.addEventListener('input', function(e){\n  const el = e.target;\n  if (el.type === 'range' && (el.id === 'simMonthly' || el.id === 'simYears' || el.id === 'simTilt')) updateSimulator();\n});\n\n// Se questo codice viene eseguito, il JavaScript è attivo: nascondi l'avviso\n(function(){ const w = byId('jsWarn'); if (w) w.style.display = 'none'; })();\n\n/* ============ PONTE CON BUSSOLA (aggiunto in fase di composizione) ============ */\n(function(){\n  const avvisa = (evento, dati) => { try { parent.postMessage(Object.assign({ bussola: \"mfo\", evento }, dati || {}), \"*\"); } catch (e) {} };\n  const pulisci = t => String(t == null ? \"\" : t).replace(/[\\u{1F000}-\\u{1FFFF}\\u{2600}-\\u{27BF}\\u{2B00}-\\u{2BFF}️‍]/gu, \"\").replace(/\\s+/g, \" \").trim();\n  /* dentro Bussola la pagina non scorre da sola: chiede all'app di tornare in cima */\n  window.scrollTo = function(){ avvisa(\"inCima\"); };\n  const avvolgi = (nome, evento) => {\n    const orig = window[nome]; if (typeof orig !== \"function\") return;\n    window[nome] = function(){ const r = orig.apply(this, arguments); avvisa(evento); return r; };\n  };\n  [\"setAnswer\", \"setPrecise\", \"toggleMulti\", \"nextStep\", \"prevStep\", \"gotoStep\", \"startWizard\"].forEach(n => avvolgi(n, \"cambio\"));\n  avvolgi(\"showResults\", \"risultati\");\n  avvolgi(\"restart\", \"ricomincia\");\n\n  window.__bussola = {\n    stato(){ return { A: JSON.parse(JSON.stringify(A)), passo: currentStep, risultati: !byId(\"results\").hidden, iniziato: byId(\"intro\").hidden }; },\n    ripristina(st){\n      if (!st || !st.A) return;\n      A = st.A;\n      if (st.risultati) { try { showResults(); return; } catch (e) {} }\n      if (st.iniziato) { byId(\"intro\").hidden = true; byId(\"wizard\").hidden = false; currentStep = Math.min(st.passo || 0, STEPS.length - 1); renderStep(); }\n    },\n    preimposta(d){\n      if (d.eta != null && !A.eta) {\n        const e = d.eta; A.eta = e < 30 ? \"u30\" : e < 40 ? \"30_39\" : e < 50 ? \"40_49\" : e < 60 ? \"50_59\" : e < 70 ? \"60_69\" : \"70p\";\n      }\n    },\n    sintesi(){\n      return QUESTIONS.filter(q => isVisible(q) && isAnswered(q))\n        .map(q => ({ sez: pulisci(SECTION_TITLES[q.step] || q.step), dom: pulisci(q.label), risp: pulisci(labelOf(q.id)) }));\n    },\n    risultati(){\n      const M = computeAll();\n      const prof = { conservativo: \"Prudente\", bilanciato: \"Bilanciato\", dinamico: \"Dinamico\" }[M.risk.profile];\n      return {\n        punteggio: computeHealthScore(M.lights), percorso: M.tierLabel,\n        patrimonioNetto: M.nw.netWorth, reddito: M.cf.income, risparmioAnno: M.cf.savingsY, tassoRisparmio: M.cf.savingsRate,\n        mesiEmergenza: M.ef.months, rateSuReddito: M.debt.rateOnIncome, investibile: M.investable,\n        profilo: prof, avvisiProfilo: (M.risk.warnings || []).map(pulisci),\n        obiettivo: pulisci(M.goalLabel), importoObiettivo: M.goal, anni: M.years,\n        proiezione: { prudente: M.projLow.final, base: M.projBase.final, favorevole: M.projHigh.final },\n        semafori: M.lights.map(l => ({ nome: pulisci(l.name), livello: l.level, perche: pulisci(l.why) })),\n        coperture: M.ins.gaps.map(g => ({ area: pulisci(g.area), livello: g.level, perche: pulisci(g.why) }))\n      };\n    }\n  };\n  /* comunica l'altezza della pagina, così l'app mostra tutto senza doppie barre di scorrimento */\n  const misura = () => avvisa(\"altezza\", { h: Math.ceil(document.documentElement.scrollHeight) });\n  if (window.ResizeObserver) new ResizeObserver(misura).observe(document.body);\n  window.addEventListener(\"load\", misura);\n  avvisa(\"pronto\");\n})();\n<\/script>\n</body>\n</html>\n";
